-- =============================================================================
-- VINFAST AI SALES COPILOT & TRAINING PLATFORM - FULL DATABASE SCHEMA & SEED
-- =============================================================================
-- Tệp SQL này dùng để:
--   1. Tái tạo toàn bộ cấu trúc bảng (30 bảng đang sử dụng) trên PostgreSQL / Supabase
--   2. Nạp toàn bộ dữ liệu chuẩn hiện tại (Tài khoản, Khách hàng, Hội thoại, AI Phân tích, Lịch hẹn...)
--   3. Dễ dàng chỉnh sửa hoặc bổ sung thêm dữ liệu mới (Xem phần mẫu ở cuối file)
--
-- Cách chạy bằng psql:
--   psql "$DATABASE_URL" -f db_handoff/recreate_and_seed_database.sql
-- Hoặc copy/paste trực tiếp vào Supabase SQL Editor.
-- =============================================================================

BEGIN;

-- Kích hoạt extension pgvector cho Kho tri thức RAG
CREATE EXTENSION IF NOT EXISTS vector;

-- =============================================================================
-- TÙY CHỌN: XÓA BẢNG CŨ ĐỂ TÁI TẠO TỪ ĐẦU (UNCOMMENT NẾU MUỐN RESET SẠCH DB)
-- =============================================================================
DROP TABLE IF EXISTS copilot_customer_facts CASCADE; -- Bảng dư thừa đã loại bỏ
/*
DROP TABLE IF EXISTS
    practice_assignment_sessions,
    practice_manager_reviews,
    practice_assignments,
    practice_checkpoints,
    practice_attempts,
    sales_copilot_lookup_sessions,
    sales_copilot_advisor_sessions,
    conversation_memories,
    copilot_messages,
    conversations,
    copilot_sessions,
    copilot_activity_details,
    copilot_milestone_history,
    copilot_activity_proposals,
    copilot_intelligence_chat,
    copilot_intelligence_analyses,
    copilot_intelligence_heads,
    copilot_recommendations_and_drafts,
    copilot_sales_preferences,
    copilot_lead_scores,
    copilot_followup_tasks,
    copilot_memories,
    copilot_customer_snapshots,
    copilot_chat_messages,
    copilot_conversations,
    copilot_customers,
    password_change_required,
    auth_sessions,
    users
CASCADE;
*/

-- =============================================================================
-- PHẦN 1: TẠO CẤU TRÚC CÁC BẢNG (DDL - CREATE TABLES & INDEXES)
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1.1. Phân hệ Xác thực & Tài khoản (Auth Module)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    user_id VARCHAR(120) PRIMARY KEY,
    username VARCHAR(120) NOT NULL UNIQUE,
    display_name VARCHAR(200) NOT NULL,
    role VARCHAR(20) NOT NULL,
    password_hash VARCHAR(256) NOT NULL,
    password_salt VARCHAR(256) NOT NULL,
    password_iterations INTEGER NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE INDEX IF NOT EXISTS ix_users_username ON users (username);

CREATE TABLE IF NOT EXISTS auth_sessions (
    token_hash VARCHAR(64) PRIMARY KEY,
    user_id VARCHAR(120) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_auth_sessions_user_id ON auth_sessions (user_id);
CREATE INDEX IF NOT EXISTS ix_auth_sessions_expires_at ON auth_sessions (expires_at);

CREATE TABLE IF NOT EXISTS password_change_required (
    user_id VARCHAR(120) PRIMARY KEY
);

-- -----------------------------------------------------------------------------
-- 1.2. Phân hệ Sales Copilot CRM, Hội thoại 2 chiều & Lịch công việc (Agenda)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS copilot_customers (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    phone VARCHAR(30),
    email VARCHAR(120),
    location VARCHAR(120),
    advisor_id VARCHAR(120) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_copilot_customers_advisor_id ON copilot_customers (advisor_id);

CREATE TABLE IF NOT EXISTS copilot_conversations (
    id VARCHAR(64) PRIMARY KEY,
    customer_id VARCHAR(64) NOT NULL REFERENCES copilot_customers(id) ON DELETE CASCADE,
    channel VARCHAR(30) DEFAULT 'zalo_oa',
    last_analyzed_at TIMESTAMPTZ,
    analysis_version INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_copilot_conversations_customer_id ON copilot_conversations (customer_id);

CREATE TABLE IF NOT EXISTS copilot_chat_messages (
    id VARCHAR(64) PRIMARY KEY,
    conversation_id VARCHAR(64) NOT NULL REFERENCES copilot_conversations(id) ON DELETE CASCADE,
    sender_role VARCHAR(20) NOT NULL,
    content TEXT NOT NULL,
    seq INTEGER NOT NULL,
    sent_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_copilot_chat_messages_conversation_id ON copilot_chat_messages (conversation_id);

CREATE TABLE IF NOT EXISTS copilot_customer_snapshots (
    customer_id VARCHAR(64) PRIMARY KEY,
    snapshot_json TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS copilot_memories (
    conversation_id VARCHAR(64) PRIMARY KEY,
    quick_summary TEXT NOT NULL DEFAULT '',
    detailed_summary TEXT NOT NULL DEFAULT '',
    timeline_json TEXT NOT NULL DEFAULT '[]',
    pending_items_json TEXT NOT NULL DEFAULT '[]',
    key_promises_json TEXT NOT NULL DEFAULT '[]',
    version INTEGER NOT NULL DEFAULT 1,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS copilot_lead_scores (
    customer_id VARCHAR(64) PRIMARY KEY,
    stage VARCHAR(40) NOT NULL DEFAULT 'discovery',
    score INTEGER NOT NULL DEFAULT 0,
    action_priority VARCHAR(20) NOT NULL DEFAULT 'medium',
    rationale TEXT NOT NULL DEFAULT '',
    breakdown_json TEXT NOT NULL DEFAULT '[]',
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS copilot_followup_tasks (
    id VARCHAR(64) PRIMARY KEY,
    customer_id VARCHAR(64),
    conversation_id VARCHAR(64),
    owner_sales_id VARCHAR(120) NOT NULL,
    task_type VARCHAR(50) NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    due_at TIMESTAMPTZ,
    due_window VARCHAR(100),
    starts_at TIMESTAMPTZ,
    ends_at TIMESTAMPTZ,
    item_type VARCHAR(20) NOT NULL DEFAULT 'task',
    priority VARCHAR(20) NOT NULL DEFAULT 'medium',
    status VARCHAR(30) NOT NULL DEFAULT 'pending',
    source_message_ids_json TEXT NOT NULL DEFAULT '[]',
    dedupe_key VARCHAR(120),
    created_at TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ,
    CONSTRAINT ck_copilot_task_interval CHECK (
        (starts_at IS NULL AND ends_at IS NULL) OR
        (starts_at IS NOT NULL AND ends_at IS NOT NULL AND ends_at > starts_at)
    ),
    CONSTRAINT ck_copilot_task_item_type CHECK (item_type IN ('task', 'appointment'))
);
CREATE INDEX IF NOT EXISTS ix_copilot_followup_tasks_customer_id ON copilot_followup_tasks (customer_id);
CREATE INDEX IF NOT EXISTS ix_copilot_followup_tasks_conversation_id ON copilot_followup_tasks (conversation_id);
CREATE INDEX IF NOT EXISTS ix_copilot_followup_tasks_owner_sales_id ON copilot_followup_tasks (owner_sales_id);
CREATE INDEX IF NOT EXISTS ix_copilot_followup_tasks_dedupe_key ON copilot_followup_tasks (dedupe_key);
CREATE INDEX IF NOT EXISTS ix_copilot_tasks_owner_schedule ON copilot_followup_tasks (owner_sales_id, starts_at, ends_at);

CREATE TABLE IF NOT EXISTS copilot_sales_preferences (
    advisor_id VARCHAR(120) PRIMARY KEY,
    nba_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    draft_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    notifications_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS copilot_recommendations_and_drafts (
    id VARCHAR(64) PRIMARY KEY,
    conversation_id VARCHAR(64) NOT NULL,
    type VARCHAR(30) NOT NULL,
    payload_json TEXT NOT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'generated',
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_copilot_recommendations_and_drafts_conversation_id
    ON copilot_recommendations_and_drafts (conversation_id);

-- -----------------------------------------------------------------------------
-- 1.3. Phân hệ Hồ sơ Trí tuệ Khách hàng (Customer Intelligence V2)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS copilot_intelligence_heads (
    customer_id VARCHAR(64) PRIMARY KEY,
    analysis_id VARCHAR(64),
    revision INTEGER NOT NULL DEFAULT 0,
    pii_mapping TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS copilot_intelligence_analyses (
    id VARCHAR(64) PRIMARY KEY,
    customer_id VARCHAR(64),
    previous_id VARCHAR(64),
    requested_at TIMESTAMPTZ,
    published_at TIMESTAMPTZ,
    payload_json TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_copilot_intelligence_analyses_customer_id
    ON copilot_intelligence_analyses (customer_id);

CREATE TABLE IF NOT EXISTS copilot_intelligence_chat (
    id VARCHAR(64) PRIMARY KEY,
    customer_id VARCHAR(64),
    analysis_id VARCHAR(64),
    advisor_id VARCHAR(120),
    created_at TIMESTAMPTZ,
    payload_json TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_copilot_intelligence_chat_customer_id ON copilot_intelligence_chat (customer_id);
CREATE INDEX IF NOT EXISTS ix_copilot_intelligence_chat_analysis_id ON copilot_intelligence_chat (analysis_id);

CREATE TABLE IF NOT EXISTS copilot_activity_proposals (
    id VARCHAR(64) PRIMARY KEY,
    customer_id VARCHAR(64),
    analysis_id VARCHAR(64),
    fingerprint VARCHAR(64) UNIQUE,
    status VARCHAR(24) NOT NULL,
    payload_json TEXT NOT NULL,
    created_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_copilot_activity_proposals_customer_id ON copilot_activity_proposals (customer_id);

CREATE TABLE IF NOT EXISTS copilot_milestone_history (
    id VARCHAR(64) PRIMARY KEY,
    customer_id VARCHAR(64),
    activity_id VARCHAR(64),
    actor_id VARCHAR(120),
    created_at TIMESTAMPTZ,
    payload_json TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_copilot_milestone_history_customer_id ON copilot_milestone_history (customer_id);
CREATE INDEX IF NOT EXISTS ix_copilot_milestone_history_activity_id ON copilot_milestone_history (activity_id);

CREATE TABLE IF NOT EXISTS copilot_activity_details (
    task_id VARCHAR(64) PRIMARY KEY,
    location TEXT NOT NULL
);

-- -----------------------------------------------------------------------------
-- 1.4. Phân hệ Trợ lý Tra cứu Tri thức AI (Copilot Knowledge Q&A Sessions)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS copilot_sessions (
    session_id VARCHAR(64) PRIMARY KEY,
    owner_id VARCHAR(120) NOT NULL,
    history_json TEXT NOT NULL,
    customer_context TEXT NOT NULL DEFAULT '',
    revision INTEGER NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_copilot_sessions_owner ON copilot_sessions (owner_id);
CREATE INDEX IF NOT EXISTS idx_copilot_sessions_expires ON copilot_sessions (expires_at);

CREATE TABLE IF NOT EXISTS conversations (
    session_id VARCHAR(64) PRIMARY KEY,
    owner_id VARCHAR(120) NOT NULL,
    title TEXT NOT NULL,
    last_seq INTEGER NOT NULL DEFAULT 0,
    customer_context TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_conversations_owner ON conversations (owner_id);
CREATE INDEX IF NOT EXISTS idx_conversations_updated ON conversations (updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_conversations_expires ON conversations (expires_at);

CREATE TABLE IF NOT EXISTS copilot_messages (
    id VARCHAR(64) PRIMARY KEY,
    session_id VARCHAR(64) NOT NULL,
    request_id VARCHAR(64),
    seq INTEGER NOT NULL,
    role VARCHAR(20) NOT NULL,
    content TEXT NOT NULL,
    metadata_json TEXT NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_copilot_messages_session ON copilot_messages (session_id);
CREATE INDEX IF NOT EXISTS idx_copilot_messages_seq ON copilot_messages (session_id, seq ASC);

CREATE TABLE IF NOT EXISTS conversation_memories (
    session_id VARCHAR(64) PRIMARY KEY,
    summary_json TEXT NOT NULL DEFAULT '{}',
    summarized_through_seq INTEGER NOT NULL DEFAULT 0,
    version INTEGER NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS sales_copilot_lookup_sessions (
    owner_id VARCHAR(120) NOT NULL,
    sales_conversation_id VARCHAR(64) NOT NULL,
    session_id VARCHAR(64) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (owner_id, sales_conversation_id),
    CONSTRAINT uq_sales_lookup_session UNIQUE (session_id)
);

CREATE TABLE IF NOT EXISTS sales_copilot_advisor_sessions (
    owner_id VARCHAR(120) PRIMARY KEY,
    session_id VARCHAR(64) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL
);

-- -----------------------------------------------------------------------------
-- 1.5. Phân hệ Kho Vector RAG (PgVector Knowledge Store)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS knowledge_vectors (
    collection_name TEXT NOT NULL,
    chunk_id TEXT NOT NULL,
    content TEXT NOT NULL,
    metadata JSONB NOT NULL,
    embedding VECTOR NOT NULL,
    PRIMARY KEY (collection_name, chunk_id)
);
CREATE INDEX IF NOT EXISTS idx_knowledge_vectors_collection ON knowledge_vectors (collection_name);

-- -----------------------------------------------------------------------------
-- 1.6. Phân hệ Luyện tập Nhập vai & Đánh giá (Roleplay Practice Module)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS practice_attempts (
    session_id VARCHAR(120) PRIMARY KEY,
    scenario_id VARCHAR(120) NOT NULL,
    advisor_id VARCHAR(120) NOT NULL,
    started_at TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ,
    evaluation_status VARCHAR(20) NOT NULL,
    ai_draft_json TEXT
);
CREATE INDEX IF NOT EXISTS ix_practice_attempts_advisor_id ON practice_attempts (advisor_id);

CREATE TABLE IF NOT EXISTS practice_checkpoints (
    session_id VARCHAR(120) PRIMARY KEY,
    state_json TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS practice_assignments (
    assignment_id VARCHAR(120) PRIMARY KEY,
    manager_id VARCHAR(120) NOT NULL,
    advisor_id VARCHAR(120) NOT NULL,
    scenario_id VARCHAR(120) NOT NULL,
    title VARCHAR(200) NOT NULL,
    due_date DATE,
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_practice_assignments_advisor_id ON practice_assignments (advisor_id);

CREATE TABLE IF NOT EXISTS practice_assignment_sessions (
    session_id VARCHAR(120) PRIMARY KEY REFERENCES practice_attempts(session_id) ON DELETE CASCADE,
    assignment_id VARCHAR(120) NOT NULL REFERENCES practice_assignments(assignment_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_practice_assignment_sessions_assignment_id ON practice_assignment_sessions (assignment_id);

CREATE TABLE IF NOT EXISTS practice_manager_reviews (
    session_id VARCHAR(120) PRIMARY KEY REFERENCES practice_attempts(session_id) ON DELETE CASCADE,
    manager_id VARCHAR(120) NOT NULL,
    reviewed_at TIMESTAMPTZ NOT NULL,
    change_reason TEXT NOT NULL,
    approved_result_json TEXT NOT NULL
);

