INSERT INTO copilot_conversations (id, customer_id, last_analyzed_at, analysis_version, created_at, updated_at) VALUES ('54ae4a6deccd4eb1aeaa07372bc615c8', 'f34945f4b57645b3a994c09899838fda', NULL, 0, '2026-10-18T04:09:11.124753+00:00', '2026-10-18T04:09:11.352164+00:00') ON CONFLICT (id) DO UPDATE SET customer_id = EXCLUDED.customer_id, last_analyzed_at = EXCLUDED.last_analyzed_at, analysis_version = EXCLUDED.analysis_version, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_conversations (id, customer_id, last_analyzed_at, analysis_version, created_at, updated_at) VALUES ('525cbd28d66d4d9682fa82e09cd7c6a1', '33f26f944c6b426687617bc8700a74dd', NULL, 0, '2026-10-18T04:09:13.870114+00:00', '2026-10-18T04:09:14.020363+00:00') ON CONFLICT (id) DO UPDATE SET customer_id = EXCLUDED.customer_id, last_analyzed_at = EXCLUDED.last_analyzed_at, analysis_version = EXCLUDED.analysis_version, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('25ce11a466f147c992b2ec609e34e0b4', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'sales', 'Em chào chị Phương ạ! Em thấy chị đang quan tâm dòng xe mini đô thị VF 3 bên em. Chị đang tìm xe mua đi làm hay đưa đón các bé đi học thế ạ?', 1, '2026-10-16T12:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('38a5f357bb3145ea956c830c9ed16607', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'customer', 'Chào em, nhà chị ở khu đô thị Vinhomes Ocean Park Gia Lâm, muốn mua thêm chiếc xe nhỏ thứ hai trong nhà để chị đưa đón con đi học và đi chợ quanh khu cho đỡ mưa nắng.', 2, '2026-10-16T12:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fabda951b224430cbc7f2e693285bd38', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'sales', 'Dạ đi nội khu Ocean Park và bán kính 10-15 km quanh Gia Lâm thì VF 3 đúng là chân ái luôn chị ạ! Xe nhỏ gọn dễ quay đầu, gầm cao 191 mm leo vỉa hay qua đường ngập nhẹ rất khỏe.', 3, '2026-10-16T12:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('35d28f631db24c9f85935ea41b9b82ee', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'customer', 'Chị cao 1m58, mới lấy bằng B1 được 2 tháng nên hơi ngại xe to. Nhưng hàng ghế sau VF 3 ngồi 2 đứa trẻ con cấp 1 với đống cặp sách có chật lắm không em?', 4, '2026-10-16T13:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('300091bc53df4432b56574c8eda7d5c7', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'sales', 'Dạ hai bé cấp 1 ngồi hàng ghế sau VF 3 rất thoải mái chị ạ! Trần xe thiết kế vuông vức nên khoảng sáng đầu thoáng, cặp sách của hai bé để ở cốp sau hoặc dưới chân đều vừa vặn.', 5, '2026-10-16T13:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('66fa73b9d40a467eafd964991f92204b', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'customer', 'Giá mua đứt luôn pin bây giờ tổng lăn bánh hết bao nhiêu tiền em? Chị định trả thẳng luôn.', 6, '2026-10-16T13:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('dbb9b0cf3e1649f3b3b2c3dc3bd40f81', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'sales', 'Dạ VF 3 bản mua kèm pin giá niêm yết 322 triệu, trừ các chương trình ưu đãi hiện tại và cộng chi phí biển số Hà Nội 20 triệu thì tổng lăn bánh rơi vào khoảng hơn 315-320 triệu một chút thôi chị ạ.', 7, '2026-10-16T13:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('62e3577841474338a0e868184258824e', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'customer', 'Chị thích màu hồng phấn hoặc màu vàng nóc trắng, hiện tại đặt cọc thì bao lâu có xe giao?', 8, '2026-10-16T13:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('08ecc5d7b62545e291e0e09730cfa6ae', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'sales', 'Dạ màu Vàng nóc trắng bên em đang có sẵn 1 xe trong kho chờ ghép hồ sơ tuần này, còn màu Hồng phấn thì dự kiến khoảng 10-14 ngày là xe về tới đại lý chị ạ.', 9, '2026-10-16T13:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('910eee75b405455999f81429f9aa4ca8', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'customer', 'Xe có sẵn camera lùi chưa em nhỉ? Chị mới lái nên sợ nhất khoản lùi chuồng.', 10, '2026-10-16T13:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ae00e04924ce4c67914bcbbf8562901a', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'sales', 'Dạ xe nguyên bản có cảm biến lùi phía sau, còn camera lùi tích hợp trực tiếp lên màn hình giải trí 10 inch thì bên đại lý em đang có gói phụ kiện lắp chính hãng tặng kèm hoặc hỗ trợ giá ưu đãi, hiển thị nét căng cả ban đêm luôn ạ.', 11, '2026-10-16T13:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ff7168497b774e048d41a3a2f4a38e1f', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'customer', 'Thế tốt quá. Sạc đầy 1 lần thì chị đi loanh quanh trong khu được mấy ngày?', 12, '2026-10-16T13:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('907093c35afc45208e769e8d9ed963e2', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'sales', 'Dạ một lần sạc đầy VF 3 đi được khoảng 180-210 km thực tế trong phố. Nếu mỗi ngày chị đưa đón bé và đi chợ tầm 15 km thì khoảng 10 ngày đến 2 tuần chị mới phải sạc 1 lần ở ngay trụ sạc trong Ocean Park ạ.', 13, '2026-10-16T13:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5d9c5774ef0d4974a10193723995047d', '06ce3e6b6c3e41c28e23483aa70ac8c8', 'customer', 'Giữ cho chị thông tin chiếc màu Vàng nóc trắng nhé. Tối nay chị bàn với chồng xem chốt màu Vàng hay đợi màu Hồng rồi sáng mai chị báo lại em để làm thủ tục cọc.', 14, '2026-10-16T13:30:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fa29a2002e0f48508bbfb5a51c6768ee', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Em chào anh ạ! Em là Minh Anh, nhân viên tư vấn bán hàng bên VinFast. Không biết anh đang quan tâm đến mẫu xe nào của bên em để em hỗ trợ tư vấn ạ?', 1, '2026-10-12T10:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('195b9a43de4547f2a177f48a440a0f9b', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Anh chưa xác định được sẽ mua mẫu nào, tài chính anh tầm 700 thì bên em có mẫu nào phù hợp không? Giới thiệu cho anh một vài mẫu đi.', 2, '2026-10-12T10:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a2007b17862b42df85fac442f4d10152', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Dạ, tầm 700 triệu thì bên em có mấy mẫu khá phù hợp anh ạ. Ví dụ như VF 5 giá khoảng 496 triệu, VF 6 Eco khoảng 646 triệu, còn VF 6 Plus khoảng 699 triệu.', 3, '2026-10-12T10:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fa84b20a733e427f8c5ee0af1e61c29e', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Nếu anh thích xe rộng và kiểu dáng thể thao hơn thì có thể xem thêm VF 7, nhưng mẫu này giá sẽ cao hơn ngân sách mình một chút.', 4, '2026-10-12T10:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('77559c55f0b34dcaa6ea6864e4af4093', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Trong các mẫu trên thì em thấy VF 6 khá đáng cân nhắc, xe 5 chỗ, không gian ổn, đi phố hay đi xa đều được.', 5, '2026-10-12T10:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8636759017fa4de8bbf2c8a7975a75d6', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Mà 700 triệu này là anh tính cả chi phí lăn bánh luôn hay chỉ riêng tiền xe thôi ạ?', 6, '2026-10-12T10:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8ea38390fd8546b6bb05d38d1016c31a', '2f56ed8c652947c69163dbcce6d39f58', 'customer', '700 triệu là tổng chi phí lăn bánh luôn em ạ, nhu cầu anh cũng cơ bản thôi, đi lại hằng ngày miễn sao pin ok tí là được.', 7, '2026-10-12T10:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9c39b2b373cb40e0895ff6e1c673ba57', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Dạ, thế thì em nghiêng về VF 6 Eco hơn anh ạ. Bản này có quãng đường di chuyển công bố khoảng 485 km mỗi lần sạc đầy theo chuẩn NEDC.', 8, '2026-10-12T10:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1d19bb41db4947f6b1f739db23acb9b1', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'So với VF 5 thì VF 6 rộng rãi, thoải mái hơn, mà vẫn có khả năng nằm trong ngân sách của anh nếu tính các ưu đãi phù hợp.', 9, '2026-10-12T10:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('783a5fa1712246568b3ae162f98af4a4', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Bình thường một ngày anh đi khoảng bao nhiêu km nhỉ? Để em tính thử xem tần suất sạc có tiện cho anh không.', 10, '2026-10-12T10:52:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('dd3b728c14694a1c851fde5e1b57e92a', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Chắc khoảng 30–40 km đó em.', 11, '2026-10-12T10:55:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('370d82c4b0164e3a97a996ff72bee561', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'À, thế thì cũng không nhiều đâu anh. Nếu đi tầm đấy thì VF 6 Eco đáp ứng khá thoải mái.', 12, '2026-10-12T10:58:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4d4243076d684cd3834db1df97bfeb7c', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Quãng đường thực tế còn tùy cách chạy và điều hòa, nhưng với mức sử dụng của anh thì thường không cần sạc mỗi ngày.', 13, '2026-10-12T11:01:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8f770ea3cd5244ea84801492a7ab46aa', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Mà anh đang ở nhà riêng hay chung cư nhỉ? Vì xe điện thì em nghĩ mình cũng nên tính trước chỗ sạc cho thuận tiện.', 14, '2026-10-12T11:04:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b5c617bd99604fbe84033f184c132b34', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Anh đang ở chung cư ở khu vực Long Biên em ạ.', 15, '2026-10-12T11:07:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('79c4bb5a2ae946c695fc66bad24d7896', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Dạ, Long Biên cũng có một số điểm sạc VinFast anh ạ. Nhưng quan trọng nhất vẫn là có trạm nào gần chung cư của mình không.', 16, '2026-10-12T11:10:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0762867d9c5f4126a49eff7a920ca9f7', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Nếu ngay dưới hầm có trạm sạc thì quá tiện rồi. Còn nếu phải đi xa để sạc thì mình nên cân nhắc kỹ hơn một chút.', 17, '2026-10-12T11:13:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8811890ca7f04c7ca4efe258e37032ab', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Anh ở chung cư nào bên Long Biên vậy ạ? Em xem thử khu vực gần đó có điểm sạc phù hợp không.', 18, '2026-10-12T11:16:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e322cac254e440209504097bf5af3905', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Với giá 700 thì nếu chiếc em giới thiệu so với CX-5 thì đâu hơn mấy đâu nhỉ?', 19, '2026-10-12T11:19:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e9571f2f29cd4cbc88900de55040b0df', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'À, anh đang tham khảo cả Mazda CX-5 nữa đúng không ạ? 😄', 20, '2026-10-12T11:22:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('041e6611db7c450e9c75dcfab7419783', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Đúng là giá xe hai bên không cách nhau quá nhiều nếu chỉ nhìn giá niêm yết. Nhưng CX-5 bản Deluxe giá khoảng 699 triệu thì lăn bánh ở Hà Nội thường sẽ cao hơn 700 triệu, còn tùy ưu đãi đại lý nữa.', 21, '2026-10-12T11:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('bd4e34c6b43f42fbbcd16bccb1c7d333', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'VF 6 Eco thì có lợi thế về chi phí sử dụng, xe chạy êm và bảo dưỡng cũng có thể tiết kiệm hơn.', 22, '2026-10-12T11:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('987da1469e354ad990f4d4b11323c486', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Còn CX-5 là SUV hạng C nên không gian rộng hơn, với xe xăng thì đi xa cũng chủ động hơn về việc tiếp nhiên liệu.', 23, '2026-10-12T11:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ee313d5066534131b94da0c8e9b788da', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Anh đang thích CX-5 vì kiểu dáng hay vì không gian xe rộng hơn ạ?', 24, '2026-10-12T11:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c3590e478f244d1dab4099a0dcc2f7b0', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Anh thấy không gian CX-5 khá rộng rãi.', 25, '2026-10-12T11:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('59316378cb3c4529a0ef4948ef9de659', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Dạ, cái này thì em đồng ý với anh. CX-5 thuộc phân khúc cao hơn VF 6 nên không gian tổng thể và cốp xe có lợi thế hơn.', 26, '2026-10-12T11:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ef7e2db5cfa24c3283f6919e03310042', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Nếu anh ưu tiên xe rộng thì bên em có VF 7 Eco cũng thuộc phân khúc SUV hạng C, anh có thể tham khảo thêm. Mẫu này thiết kế thể thao, chiều dài cơ sở lớn nên chỗ để chân hàng ghế sau khá thoải mái.', 27, '2026-10-12T11:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ecca844c553447208867c20116a2636e', '2f56ed8c652947c69163dbcce6d39f58', 'customer', 'Có điều VF 7 sẽ hơi vượt ngân sách 700 triệu lăn bánh ban đầu của anh.', 28, '2026-10-12T11:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6b4f85287917484db8e41511bb7f48eb', '2f56ed8c652947c69163dbcce6d39f58', 'sales', 'Mà bình thường anh chủ yếu đi một mình hay hay chở gia đình nữa ạ? Nếu thường xuyên đi 4–5 người thì em nghĩ nên ưu tiên không gian xe ngay từ đầu.', 29, '2026-10-12T11:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('94d422e470b643f98a0984080b24c6fe', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'sales', 'Dạ em chào chị Nhung ạ! Em là Minh Anh bên VinFast. Em xin phép hỗ trợ thông tin về mẫu xe VF 6 mà chị đang quan tâm nhé ạ.', 1, '2026-10-17T15:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f80b3cc1f3ba44bc8c7b505940792dce', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'customer', 'Chào em, chị đang xem giữa VF 6 Eco với Kia Seltos bản tiêu chuẩn. Chị mua xe chủ yếu để hai mẹ con đi lại trong khu Văn Quán, Hà Đông và cuối tuần về quê ở Sơn Tây.', 2, '2026-10-17T15:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e0f1cf6bbdb244c58f3282a104d670d6', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'sales', 'Dạ so với Kia Seltos bản tiêu chuẩn thì VF 6 Eco có lợi thế lớn là được miễn 100% lệ phí trước bạ (tiết kiệm khoảng 75-80 triệu tiền đăng ký), động cơ điện 174 mã lực êm ái không mùi xăng tránh say xe cho bé, và treo sau đa liên kết êm hơn treo thanh xoắn của Seltos ạ.', 3, '2026-10-17T15:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('255238d0a6da45658a33952cfd56f246', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'customer', 'Con trai chị 7 tuổi đi xe xăng rất hay bị say xe nên chị mới tìm hiểu sang xe điện đấy. Nhưng xe điện phanh tái sinh có làm người ngồi sau bị giật không em?', 4, '2026-10-17T16:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('52c0859e5b7a4bae9f477963a61e7cab', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'sales', 'Dạ trên VF 6 mình có thể chỉnh mức phanh tái sinh về mức Thấp hoặc Tắt đi khi đi trong phố, lúc đó xe trôi mượt y hệt xe xăng số tự động nhưng lại hoàn toàn không có tiếng ồn động cơ và mùi xăng nên trẻ nhỏ không bị say xe chị ạ.', 5, '2026-10-17T16:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1b678674f6294e039484c4b88cc8cd62', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'customer', 'Tổng lăn bánh VF 6 Eco mua kèm pin ở Hà Nội bây giờ là bao nhiêu em? Chị có sẵn 350 triệu, muốn vay trả góp phần còn lại trong 5 năm.', 6, '2026-10-17T16:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ea03d15e013d46e088c0b143d9f0982d', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'sales', 'Dạ VF 6 Eco kèm pin lăn bánh Hà Nội khoảng 670 triệu. Chị trả trước 350 triệu thì chỉ vay ngân hàng 320 triệu trong 5 năm (60 tháng), mỗi tháng đóng cả gốc và lãi khoảng 7,4 triệu đồng thôi ạ.', 7, '2026-10-17T16:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2e859ad78bcf4d05972af974ac975e06', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'customer', 'Ở quanh hồ Văn Quán Hà Đông có nhiều điểm sạc không em? Nhà chị ở tập thể cũ không đỗ xe trong nhà để cắm sạc đêm được.', 8, '2026-10-17T16:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c82162d3809340389e2c4f9af3baf1af', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'sales', 'Dạ quanh khu Văn Quán, siêu thị Big C Hồ Gươm Plaza và dọc đường Trần Phú, Nguyễn Khuyến đều có cụm trụ sạc nhanh V-GREEN chị ạ! Chị chỉ cần tranh thủ lúc đi siêu thị cuối tuần cắm sạc 30 phút là đủ đi cả tuần lễ luôn.', 9, '2026-10-17T16:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f1327f343b774ba3850e503a7600bfae', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'customer', 'À ở ngay Hồ Gươm Plaza có trạm sạc thì quá tiện vì tuần nào chị cũng cho bé ra đấy chơi. Màu Trắng hoặc màu Đỏ bản Eco có sẵn xe không em?', 10, '2026-10-17T16:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6076b8b8de054005a1886a412f24815e', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'sales', 'Dạ bản VF 6 Eco màu Trắng và màu Đỏ bên em đều đang có xe trong lô phân bổ tháng này chị ạ.', 11, '2026-10-17T16:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('bb4937d2bdae41349ac5a81035dd26d4', '398a18b8b26c4f06a4a27ee3a4e4f4d0', 'customer', 'Chiều Chủ nhật tuần này khoảng 15h00 chị cho bé qua ngồi thử xem cháu có ưng và đỡ mùi xe không nhé, gửi trước cho chị bảng tính trả góp vay 320 triệu.', 12, '2026-10-17T16:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b293eeb98147454a86fd6327c219d401', '3f1203aa553647058bc773ceb9dbf612', 'customer', 'Chào em, anh đang tìm hiểu mẫu VF 7 Plus, bên em có xe trưng bày và xe lái thử không?', 1, '2026-10-16T08:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d211c66fcfae4a4f9eb0ccca948fb378', '3f1203aa553647058bc773ceb9dbf612', 'sales', 'Em chào anh Nam ạ! Dạ showroom bên em đang có sẵn cả xe VF 7 Plus trưng bày lẫn xe lái thử bản 2 cầu và 1 cầu luôn ạ. Anh đang quan tâm bản VF 7 Plus 1 cầu hay 2 cầu AWD thế ạ?', 2, '2026-10-16T08:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('808721bb08744ed199086d2810b43c66', '3f1203aa553647058bc773ceb9dbf612', 'customer', 'Anh thích cảm giác lái bốc nên đang nhắm bản Plus 2 cầu trần kính. Nhưng nghe nói bản 2 cầu tốn pin hơn bản 1 cầu khá nhiều đúng không em?', 3, '2026-10-16T08:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('77566aa2d1cd4325b7f732d2da099e66', '3f1203aa553647058bc773ceb9dbf612', 'sales', 'Dạ bản Plus 2 cầu công suất tới 349 mã lực, mô-men xoắn 500 Nm nên đạp ga rất dính lưng anh ạ. Về quãng đường công bố WLTP thì bản 2 cầu đạt 431 km/lần sạc đầy, thực tế đi hỗn hợp rơi vào khoảng 360-380 km.', 4, '2026-10-16T09:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5165cccdee7a457987b26cbeaf631f27', '3f1203aa553647058bc773ceb9dbf612', 'customer', 'Anh đang chạy Mazda CX-5 đời 2021, muốn đổi sang xe điện. Bên em có hỗ trợ thu cũ đổi mới không?', 5, '2026-10-16T09:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e33acdb08e304cdeb258f9890c65a700', '3f1203aa553647058bc773ceb9dbf612', 'sales', 'Dạ có anh ơi! Chương trình Thu cũ - Đổi mới FGF hỗ trợ định giá xe cũ minh bạch tại chỗ và còn được tặng thêm ưu đãi khi lên đời xe VinFast mới nữa ạ.', 6, '2026-10-16T09:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e26b7ddc162f438582e2be87d1ea413a', '3f1203aa553647058bc773ceb9dbf612', 'customer', 'Nếu bán CX-5 đi thì anh dự kiến đưa trước khoảng 500 triệu, phần còn lại anh muốn vay trả góp trong 5 năm thì mỗi tháng trả gốc cộng lãi khoảng bao nhiêu?', 7, '2026-10-16T09:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5910724448334b10a4ccc1cd819e226b', '3f1203aa553647058bc773ceb9dbf612', 'sales', 'Dạ nếu anh trả trước 500 triệu cho VF 7 Plus AWD kèm pin, khoản vay còn lại khoảng 450-470 triệu trong 5 năm (60 tháng). Với gói lãi suất ưu đãi hiện tại thì gốc và lãi tháng đầu khoảng hơn 10,5 triệu và giảm dần theo dư nợ anh ạ.', 8, '2026-10-16T09:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3c83df364132470fbff682d664cfd1ee', '3f1203aa553647058bc773ceb9dbf612', 'customer', 'Thủ tục vay theo lương cá nhân có cần chứng minh thu nhập phức tạp không em? Anh nhận lương chuyển khoản qua Vietcombank.', 9, '2026-10-16T09:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7ce2a151cf38479f886f1b2293654b98', '3f1203aa553647058bc773ceb9dbf612', 'sales', 'Dạ lương chuyển khoản qua Vietcombank thì hồ sơ cực kỳ gọn anh ạ, chỉ cần sao kê 6 tháng gần nhất và CCCD, ngân hàng duyệt thông báo cho vay trong vòng 24h thôi ạ.', 10, '2026-10-16T09:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e84bd09f931f49f1bb56bf1001d11ff0', '3f1203aa553647058bc773ceb9dbf612', 'customer', 'Còn vụ trần kính toàn cảnh của VF 7 đi mùa hè Hà Nội có bị nóng đầu không? Anh thấy không có rèm kéo cơ.', 11, '2026-10-16T09:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e780d8ffcd5841e8b82e41fcfa87f08c', '3f1203aa553647058bc773ceb9dbf612', 'sales', 'Dạ kính trần VF 7 là kính Low-E cách nhiệt và chống tia UV tới 99% anh ạ. Ngoài ra khi nhận xe bên em có thể tặng kèm bộ rèm trần tháo lắp chuyên dụng cho mùa nắng gắt Hà Nội nên anh hoàn toàn yên tâm.', 12, '2026-10-16T09:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0cc9563e806b423f8c3ae1e37e54091a', '3f1203aa553647058bc773ceb9dbf612', 'customer', 'Nhà anh ở ngõ phố Khương Trung, ô tô đỗ trong sân nhà được thì lắp bộ sạc treo tường 7.4kW có cần điện 3 pha không?', 13, '2026-10-16T09:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e5aeda4688fa46a5a7ae52d4d58f8c42', '3f1203aa553647058bc773ceb9dbf612', 'sales', 'Dạ bộ sạc treo tường AC 7,4 kW dùng điện 1 pha sinh hoạt gia đình bình thường anh nhé, chỉ cần dây dẫn đủ tiết diện và aptomat riêng là sạc qua đêm từ 20% lên 100% mất khoảng 8 tiếng thôi ạ.', 14, '2026-10-16T09:30:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('21ed11fdfd4b445286c2213f411514dc', '3f1203aa553647058bc773ceb9dbf612', 'customer', 'Ok em, gửi cho anh bảng tính dòng tiền trả góp 60 tháng và hẹn bên thẩm định xe cũ chiều Chủ nhật tuần này lúc 14h30 qua xem con CX-5 giúp anh nhé.', 15, '2026-10-16T09:33:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2cf6e08fcc2f48a1969fd05a6246b22a', '518f872cafdd47ae8ed54c7ae61f6beb', 'customer', 'Chào em, anh đang muốn đặt mua 1 chiếc VF 3 màu Xanh bộ đội hoặc Xám xi măng để độ thêm phụ kiện đi cà phê cuối tuần.', 1, '2026-10-17T16:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3172a3733a514d9aa449ec8c344c631f', '518f872cafdd47ae8ed54c7ae61f6beb', 'sales', 'Dạ em chào anh Khoa! VF 3 màu Xanh rêu bộ đội và Xám xi măng đang là 2 màu hot nhất cho các anh thích phong cách thể thao, dã ngoại đấy ạ. Anh định lấy bản mua luôn pin đúng không ạ?', 2, '2026-10-17T16:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b3600fea98674cf5980d4d5aafc8cdd5', '518f872cafdd47ae8ed54c7ae61f6beb', 'customer', 'Đúng rồi em, anh mua đứt pin luôn và trả thẳng 100%, không vay. Nhưng anh muốn hỏi nếu thay mâm đúc với lắp giá nóc thì có bị từ chối bảo hành phần điện hay pin không?', 3, '2026-10-17T16:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('dd124bfc17054dc9be97304fc8194e99', '518f872cafdd47ae8ed54c7ae61f6beb', 'sales', 'Dạ nếu anh giữ đúng thông số kích thước lốp 16 inch theo đăng kiểm và lắp giá nóc, phụ kiện chính hãng hoặc không cắt trích đấu nối vào hệ thống dây điện nguyên bản của xe thì chế độ bảo hành pin và động cơ vẫn được giữ nguyên anh nhé!', 4, '2026-10-17T17:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('68dbddaed32b4975ba49402cd5774765', '518f872cafdd47ae8ed54c7ae61f6beb', 'customer', 'Tại đại lý bên em có gói độ sẵn mâm đúc, bọc ghế da với dán phim cách nhiệt 3M luôn không để anh làm một thể trước khi nhận xe?', 5, '2026-10-17T17:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f5434cb1554a4062aa76bf0db300dd36', '518f872cafdd47ae8ed54c7ae61f6beb', 'sales', 'Dạ xưởng dịch vụ bên em có đầy đủ combo nâng cấp chính hãng cho VF 3 gồm: bộ mâm hợp kim thể thao, bọc ghế da Nappa phối màu theo ý thích, thảm sàn đúc, camera lùi và phim cách nhiệt 3M Crystalline bảo hành 10 năm luôn ạ.', 6, '2026-10-17T17:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('62fdff528f524982b0d29991922c3e8a', '518f872cafdd47ae8ed54c7ae61f6beb', 'customer', 'Combo phụ kiện đấy tổng khoảng bao nhiêu tiền em?', 7, '2026-10-17T17:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c508b73b4959490fb72e0b479d27fdcb', '518f872cafdd47ae8ed54c7ae61f6beb', 'sales', 'Dạ trọn bộ cả mâm đúc, ghế da, phim cách nhiệt 3M và camera lùi đang được ưu đãi combo cho khách mua xe mới chỉ khoảng 18 - 22 triệu tùy mẫu mâm anh chọn ạ.', 8, '2026-10-17T17:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('454a445c9a524034897c2dcc1d7417da', '518f872cafdd47ae8ed54c7ae61f6beb', 'customer', 'Giá hợp lý đấy. Thế màu Xám xi măng hiện tại có xe sẵn số VIN để bấm biển ngay trong tuần này không?', 9, '2026-10-17T17:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('064cff3e1beb4d649b5d2b57f0c5a42c', '518f872cafdd47ae8ed54c7ae61f6beb', 'sales', 'Dạ màu Xám xi măng bên em đang có sẵn đúng 1 xe có hồ sơ xuất xưởng sẵn tại đại lý, anh thanh toán xong là hôm sau đi bấm biển Hà Nội được ngay ạ!', 10, '2026-10-17T17:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3c4954287bed4b1da2587eda3a1fda52', '518f872cafdd47ae8ed54c7ae61f6beb', 'customer', 'Ok chốt giữ chiếc Xám xi măng đó cho anh nhé. Gửi mẫu các kiểu mâm đúc với mẫu ghế da qua tin nhắn cho anh chọn, sáng mai 10h anh qua showroom đặt cọc và ký hợp đồng.', 11, '2026-10-17T17:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3a618f030e764364889b1e5d51b97684', '518f872cafdd47ae8ed54c7ae61f6beb', 'sales', 'so sánh vf 5 và vf 7', 12, '2026-10-17T22:32:21.801214+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6a0cd56500c74469989242b871f0d030', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Em ơi, VF 3 giờ giá bao nhiêu nhỉ?', 1, '2026-10-16T16:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b3fe8413b0f0473299935c0e4d223a9a', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Dạ, VF 3 Eco giá niêm yết tham khảo từ 285 triệu, còn bản Plus từ 296 triệu anh nhé. Anh đang muốn lấy xe luôn hay mới tìm hiểu thôi?', 2, '2026-10-16T16:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ecbef01fcd08456698c8ccdab4e61d15', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Anh đang xem thôi. Tầm này mua VF 3 ổn không em? Anh thấy ngoài đường chạy nhiều phết.', 3, '2026-10-16T16:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cb2ac0eea3144de884ca8296765056b8', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Nếu chủ yếu đi trong phố thì ổn anh. Xe nhỏ, dễ luồn lách, đỗ xe cũng tiện. Nhưng VF 3 chỉ có 4 chỗ nên nếu nhà mình đông người thì hơi hạn chế.', 4, '2026-10-16T16:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('11af52174a0b468591436c0720476cf3', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Nhà anh 3 người, hai vợ chồng với đứa nhỏ 4 tuổi.', 5, '2026-10-16T16:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b6572e32418444e9b8dc4cd66d4e2c4e', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Vậy vẫn dùng được anh. Nhưng em hỏi thêm, nhà mình có hay về quê hoặc đi chơi xa không?', 6, '2026-10-16T16:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7959e25c279d4cc888d818604a06757b', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Có chứ, tháng chắc về Bắc Ninh 1–2 lần. Còn lại anh đi làm ở Cầu Giấy, nhà ở Nam Từ Liêm.', 7, '2026-10-16T16:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6280d064f7394740a9f9a2b339a1cd1a', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Quãng đường như thế VF 3 đáp ứng được. Nhưng vì anh có con nhỏ nên em nghĩ anh nên xem cả VF 5 nữa, xe 5 chỗ, không gian và cốp thoải mái hơn.', 8, '2026-10-16T16:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('bf7847bf80bc4051b55bf3376b7be175', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'VF 5 tận gần 500 triệu mà em. Anh cố lắm chắc chỉ có 150 triệu tiền mặt thôi.', 9, '2026-10-16T16:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f689fd3d57cc46bbb4661f83f9aa81cc', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'À, vậy anh đang tính vay ngân hàng phần còn lại đúng không?', 10, '2026-10-16T16:39:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8b3964564b3d44ec9aad412478807bda', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Ừ. Nhưng mỗi tháng trả tầm 5 triệu đổ lại thôi. Cao quá thì mệt.', 11, '2026-10-16T16:42:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f6dc247c6a3b46fb989d8cc10e71ac0d', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Nếu giới hạn 5 triệu/tháng thì em nghĩ nên tính kỹ, vì ngoài tiền vay còn gửi xe, bảo hiểm và các chi phí sử dụng khác.', 12, '2026-10-16T16:45:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('db7b9d9bf6f84b639dd3c4793239ab23', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Anh đang muốn trả góp trong mấy năm?', 13, '2026-10-16T16:48:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f6ad58b579d047968356704f3e86af98', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', '5 năm đi. Anh không muốn vay lâu quá.', 14, '2026-10-16T16:51:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('56dcdc3cf26e40c28ef668072fc8327b', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Em tính sơ bộ để anh hình dung nhé. Giả sử mua VF 3 khoảng 285 triệu, mình có sẵn 150 triệu và vay 135 triệu trong 5 năm.', 15, '2026-10-16T16:54:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('375eb4799a8349dc8a156eafa46ca3f1', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Nếu giả định lãi 9%/năm, trả gốc đều hằng tháng, tháng đầu khoảng 3,26 triệu, các tháng sau giảm dần. Đây chỉ là ví dụ, chưa phải phương án được ngân hàng duyệt.', 16, '2026-10-16T16:57:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fd18bcbb1ba5454e8cd70ee28565abb1', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Ơ anh tưởng trả góp là tháng nào cũng bằng nhau chứ?', 17, '2026-10-16T17:00:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d38abf1b46594b1aabb8a89cf1017682', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Có nhiều cách trả anh. Ví dụ trả gốc đều thì tổng tiền giảm dần, còn trả số tiền tương đối cố định thì ngân hàng sẽ tính theo phương thức khác.', 18, '2026-10-16T17:03:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e49685381d484a6d9dc7f7f24f04c43d', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Khi có phương án cụ thể em sẽ gửi anh cả lịch trả nợ, không chỉ báo mỗi số tiền tháng đầu.', 19, '2026-10-16T17:06:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('048d41d8fa7047f3bbb0db753eeadd17', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Thế nếu anh vay 200 triệu để giữ lại ít tiền phòng thân thì sao?', 20, '2026-10-16T17:09:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('64226eb12cf54f658ab0c7da90ba71d5', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Vẫn có thể tính thử anh. Với cùng giả định 9%/năm và 60 tháng, vay 200 triệu thì tháng đầu khoảng 4,83 triệu theo cách trả gốc đều.', 21, '2026-10-16T17:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6a207e7e56704a7abbbe0a2321691e82', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Nhưng số đó chưa gồm phí khác, và lãi suất thực tế có thể thay đổi sau thời gian ưu đãi.', 22, '2026-10-16T17:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('93538cee853c49aa80bc4f2a8e480fd1', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Nghe cũng vừa. Nhưng anh không thích kiểu ban đầu lãi thấp xong sau tăng lên đâu.', 23, '2026-10-16T17:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('94ab7e29c8774de0bf48e6bd7894aa15', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Vâng, cái đó phải hỏi rõ từ đầu. Em sẽ ưu tiên phương án có thông tin minh bạch về lãi sau ưu đãi, phí trả trước hạn và tổng tiền phải trả. Chứ chỉ nhìn lãi suất năm đầu thì dễ hiểu nhầm lắm.', 24, '2026-10-16T17:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8c7fca105be94f3c890ddbb9945cc62a', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Mà VF 3 bé thế, đi cao tốc có ổn không? Thấy xe trông như đồ chơi ấy.', 25, '2026-10-16T17:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9d004bfa13464b91937be4335343e7a4', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Haha, nhiều khách nhìn ảnh cũng nói vậy anh. Xe nhỏ thật, không phải kiểu rộng rãi như SUV thông thường.', 26, '2026-10-16T17:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ce16c70c3dc74fe6bc65fd22201f1356', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'VF 3 vẫn có thể sử dụng trên những tuyến đường được phép và phù hợp điều kiện vận hành. Nhưng nếu anh thường xuyên chạy cao tốc, chở cả nhà và nhiều đồ thì VF 5 hợp hơn.', 27, '2026-10-16T17:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1a54f1b248e049cfb04354d66cd75b72', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Thế tại sao lúc đầu em bảo VF 3 ổn?', 28, '2026-10-16T17:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('61bcf712077f40fbb30c2d42e0ff0898', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Vì ban đầu em hiểu anh chủ yếu đi làm trong phố và có ngân sách giới hạn. Với nhu cầu đó VF 3 là lựa chọn hợp lý về chi phí.', 29, '2026-10-16T17:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5841d94a9b22496994bccf474a71ac8a', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Nhưng nếu anh đặt nặng chuyện đi xa và sự thoải mái của cả gia đình thì em sẽ nghiêng về VF 5 hơn. Hai mẫu phục vụ nhu cầu hơi khác nhau.', 30, '2026-10-16T17:39:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3a5021f0a42c48059bf558364929cc6e', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'VF 5 hơn VF 3 những gì đáng tiền?', 31, '2026-10-16T17:42:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('99a6a3a3711e41778e5f4893378fd259', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Dễ thấy nhất là VF 5 có 5 chỗ ngồi, khoang hành lý thực dụng hơn và kích thước lớn hơn. Công suất cũng cao hơn đáng kể.', 32, '2026-10-16T17:45:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e779ab2aecc64959a8c51ee6c9c0286a', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Về pin, VF 3 có quãng đường công bố khoảng 215 km còn VF 5 khoảng 326 km mỗi lần sạc theo NEDC. Đi thực tế sẽ tùy điều kiện.', 33, '2026-10-16T17:48:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('50215a5d58c747db8962fb35758b0825', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Thế chênh gần 200 triệu, anh thấy không đáng lắm.', 34, '2026-10-16T17:51:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5fd27ec8b27744809fc640e522758d7e', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Nếu tính riêng tiền mua xe thì đúng là chênh nhiều anh. Em cũng không nghĩ ai mua VF 3 cũng nên cố lên VF 5.', 35, '2026-10-16T17:54:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7bc91a6e0f27424290692b3f2cefbb30', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Với 150 triệu sẵn có thì VF 3 nhẹ gánh tài chính hơn hẳn. VF 5 chỉ đáng lên nếu anh thực sự cần thêm không gian và khả năng sử dụng đa dạng.', 36, '2026-10-16T17:57:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e3bab39a61194caba1ecf1bb43b2ccef', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Anh chỉ sợ mua VF 3 xong được một năm lại thấy chật.', 37, '2026-10-16T18:00:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4a4b0b8175874d0d8c4bfd3b39ed6fa8', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Cái đấy có khả năng xảy ra, nhất là con anh lớn thêm, gia đình bắt đầu mang nhiều đồ khi đi chơi.', 38, '2026-10-16T18:03:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0e7cc30b2151479d9bafca8ff2341645', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Hay thế này, anh thử đưa cả vợ con qua xem xe. Cho bé ngồi thử ghế sau, đặt thử ghế trẻ em và xem cốp có đủ đồ không. Cảm nhận thực tế sẽ dễ quyết hơn.', 39, '2026-10-16T18:06:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('832ea67434db4e41a733803d70302e4b', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Nghe hợp lý. Nhưng vợ anh lại đang thích xe xăng. Bảo xe điện vài năm pin hỏng là vứt.', 40, '2026-10-16T18:09:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8ecabe0e758a4a25bec18b6cddc84f71', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Cái này chắc nhiều nhà cũng tranh luận giống nhà anh', 41, '2026-10-16T18:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('10cf4270b46b48f397dbbcce5f371301', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Pin không phải cứ dùng vài năm là hỏng. Nhưng em nghĩ chị nhà có quyền lo, vì đây là khoản tiền lớn.', 42, '2026-10-16T18:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('54b145657dea4517beade32816ffd5d0', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'VF 3 hiện công bố bảo hành xe 7 năm hoặc 160.000 km, còn chính sách bảo hành pin phải xem chi tiết theo điều khoản áp dụng cho xe mình mua.', 43, '2026-10-16T18:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cc83f005ce1a43b292f4a841f0e4520f', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Thế hết bảo hành mà pin hỏng thì sao? Phải thay cả cục à?', 44, '2026-10-16T18:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('94e29c956d84419c8bb5e952c467a9a0', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Còn tùy lỗi anh. Không phải trường hợp nào cũng phải thay toàn bộ bộ pin. Cần kiểm tra để xác định bộ phận nào hỏng và phương án sửa chữa.', 45, '2026-10-16T18:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ffe058cfcf0840ac8e6d7bfc71cab024', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Chi phí thay thế ngoài bảo hành thì em sẽ không đoán, vì phụ thuộc hạng mục và giá linh kiện thời điểm đó.', 46, '2026-10-16T18:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5ddc73c372ae43ee99c3980d94ccb32c', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Ừ, nói thế anh còn tin. Chứ mấy ông sales toàn bảo pin dùng cả đời.', 47, '2026-10-16T18:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('83426f57172b4874ae4ffb0b185de4ea', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Haha, nói pin dùng cả đời thì em cũng không dám đâu anh. Thiết bị nào cũng có tuổi thọ của nó.', 48, '2026-10-16T18:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('74172cfe8d1e4610a10c44d0b9bd6f3e', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Quan trọng là mình hiểu rõ chính sách bảo hành, sử dụng đúng hướng dẫn và có phương án xử lý khi phát sinh vấn đề.', 49, '2026-10-16T18:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e4c6efb802d44aeebd41c1cd890beb52', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'À mà nếu mua VF 3 thì bên em có sẵn xe giao luôn không?', 50, '2026-10-16T18:39:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('14f422ec3f9549a988eafab5dbd53f87', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Cái này em phải kiểm tra theo màu và phiên bản anh chọn. Anh đang thích màu nào?', 51, '2026-10-16T18:42:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7be2f3ca7c6048a4afd93b58e1ceace6', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Anh thích màu xanh. Nhưng vợ anh lại thích màu trắng.', 52, '2026-10-16T18:45:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d46e1697cd9b474c855b78d287260644', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Thế chắc để chị chọn màu cho yên nhà anh ạ', 53, '2026-10-16T18:48:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6b3f1535089840bdbf9370679590c9b5', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Haha. Nhưng màu trắng dễ bẩn lắm.', 54, '2026-10-16T18:51:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('eeecaaecaf3349f782c8554bf02bc700', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Đúng, trắng thì nhìn sạch và sáng xe nhưng đi mưa bùn dễ thấy vết bẩn. Xanh thì nổi bật hơn. Anh có thể qua xem màu thực tế, ảnh trên điện thoại đôi khi lệch màu.', 55, '2026-10-16T18:54:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4c6539924cee455ebb76d16b329d3328', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Mà anh chưa có bằng lái đâu. Đang học, tháng sau mới thi.', 56, '2026-10-16T18:57:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d9c4c714805e42388b285fbb0438b58a', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'À, thế là mình đang chuẩn bị mua xe trước rồi.', 57, '2026-10-16T19:00:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d34344900b374f17b5dab3092e2a27ea', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Ừ, tính mua luôn sau khi lấy bằng. Nếu đỗ nhé, haha.', 58, '2026-10-16T19:03:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fe07a7f26ff04f8ab019ead850d225af', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Haha, vậy chúc anh thi một lần là qua. Chưa cần vội đặt cọc lúc này đâu. Anh cứ chọn mẫu xe trước, còn chuyện lấy xe mình tính theo thời điểm có bằng.', 59, '2026-10-16T19:06:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c1e804c7e9af46a5b234c7b32483f35b', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Anh sợ đợi tháng sau lại tăng giá.', 60, '2026-10-16T19:09:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1caffe3ae78a4c1d9ef21b446a3ac5dd', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Giá và ưu đãi có thể thay đổi theo từng đợt, em không đảm bảo trước được.', 61, '2026-10-16T19:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('77dcf90043a543c4b9aa58ecae6c88ff', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Nếu có chương trình áp dụng ở thời điểm anh định mua thì em sẽ gửi anh so sánh, nhưng anh đừng vì sợ tăng giá mà cọc khi mình chưa chắc về mẫu xe.', 62, '2026-10-16T19:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a32eace6b18c4cdebc2844e2e1139fb4', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Ừ. Thế em tính giúp anh 2 phương án nhé. Một cái VF 3 vay 150 triệu, một cái VF 5 vay 300 triệu, trả trong 5 năm.', 63, '2026-10-16T19:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1cc81869f1cd47f781f20e52e3f18f54', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Được anh. Em lấy cùng giả định lãi suất 9%/năm, trả gốc đều để anh dễ so sánh trước nhé.', 64, '2026-10-16T19:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('174136f09f574f37963204f90d3517d4', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Vay 150 triệu thì tháng đầu khoảng 3,63 triệu, còn vay 300 triệu thì khoảng 7,25 triệu. Các tháng sau sẽ giảm dần nếu lãi suất giữ nguyên.', 65, '2026-10-16T19:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0292a847ccd649d4bd946a7c23fe46c0', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', '7 triệu thì cao quá. Thôi VF 5 chắc bỏ.', 66, '2026-10-16T19:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0f36114394174bc89fbc7a3cb6b20575', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Vậy mình tập trung VF 3 trước. Vay 150 triệu cũng gần với mức anh muốn trả hằng tháng hơn.', 67, '2026-10-16T19:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d53842419978480c9bb6f2d34e27074e', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Nhưng em khuyên anh đừng dồn hết 150 triệu tiền mặt vào xe. Nên giữ lại một khoản dự phòng cho gia đình.', 68, '2026-10-16T19:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f8a9dfae234b4ae3821762e8ad53d4c1', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Đúng rồi. Anh cũng nghĩ thế. Thế 150 triệu vay thì ngân hàng có dễ duyệt không?', 69, '2026-10-16T19:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9f6c03f5e9be4699b2137455dcdd75be', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Còn tùy thu nhập, lịch sử tín dụng và hồ sơ của anh. Nếu công việc và thu nhập ổn định thì có cơ sở để ngân hàng xem xét, nhưng em không thể hứa chắc là duyệt.', 70, '2026-10-16T19:39:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('170f13e750de4cf0b6d835c5e23f3bab', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Anh làm văn phòng, lương chuyển khoản khoảng 18 triệu. Vợ anh cũng đi làm nhưng anh muốn tự đứng tên vay.', 71, '2026-10-16T19:42:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f309be37c71f40d8b14a53e72605b953', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Dạ, vậy mình có thể chuẩn bị hồ sơ để ngân hàng đánh giá. Em sẽ gửi anh danh sách giấy tờ cơ bản và nhờ bên hỗ trợ tài chính tư vấn phương án phù hợp.', 72, '2026-10-16T19:45:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2c2e0c90279c425f867691146f2724ce', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Ok. Em cứ gửi bảng trả góp trước nhé. Anh bàn thêm với vợ đã.', 73, '2026-10-16T19:48:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6e39f4e80e9c450295c35d345d205589', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Vâng anh. Em sẽ gửi hai phương án có lãi suất giả định và ghi rõ phần nào cần ngân hàng xác nhận, để hai vợ chồng dễ cân nhắc.', 74, '2026-10-16T19:51:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ccd0338e80a2475cb02f67d828e62b01', '525cbd28d66d4d9682fa82e09cd7c6a1', 'customer', 'Ừ, cảm ơn em.', 75, '2026-10-16T19:54:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7d35631266cd4942a7e315eb42ac0c82', '525cbd28d66d4d9682fa82e09cd7c6a1', 'sales', 'Dạ không có gì anh. Khi nào hai vợ chồng muốn qua xem xe thì nhắn em, em sắp xếp để mình xem cả VF 3 lẫn VF 5 luôn.', 76, '2026-10-16T19:57:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ef1d83878fc04548a984e4450c1bf481', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Em chào anh, em là Huy bên VinFast. Hôm trước em thấy anh có để lại thông tin quan tâm VF 8, không biết anh đã tham khảo xe ở đâu chưa ạ?', 1, '2026-10-16T10:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b38d6b4eadb14d4898ff751686976714', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Anh mới xem trên mạng thôi. Đang tính đổi xe mà vẫn hơi lăn tăn.', 2, '2026-10-16T10:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ccca01571058458abad4afc8b30c21b8', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Anh đang chạy xe gì vậy anh?', 3, '2026-10-16T10:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a79096c2d67d470eb2a59421ca7f7805', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Anh đang đi Tucson 2021. Xe cũng chưa có vấn đề gì, nhưng thấy mấy ông bạn chuyển qua xe điện nên anh muốn tìm hiểu thử.', 4, '2026-10-16T10:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cbf0eda77b484e1289420eb8de2af2fb', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'À Tucson thì xe cũng rộng và đi khá ổn rồi. Anh định đổi vì muốn tiết kiệm chi phí hay muốn trải nghiệm xe điện là chính?', 5, '2026-10-16T10:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6ea6ba9af1ac4c998e77cd9a546165ce', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Cả hai. Nhưng chủ yếu muốn xe chạy êm, rộng rãi. Nhà anh 4 người, cuối tuần hay đi chơi.', 6, '2026-10-16T10:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2729a58a000c41fe867e3984787a218b', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Vậy VF 8 khá hợp đấy anh. Xe 5 chỗ, không gian rộng, đi gia đình thoải mái. Xe điện thì tăng tốc cũng bốc hơn Tucson khá nhiều.', 7, '2026-10-16T10:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('930a3efbacd046499cbfb1d988cc59fd', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Anh đã ngồi thử VF 8 bao giờ chưa?', 8, '2026-10-16T10:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4e031c1d761645278404b72b9a8adcce', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Chưa em. Mà VF 8 giờ giá thế nào?', 9, '2026-10-16T10:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9225596b1f434e65b7895df95d701311', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'VF 8 có các phiên bản khác nhau nên giá sẽ chênh nhau anh nhé. Em chưa có bảng giá chốt theo xe tồn và ưu đãi hôm nay, nên em không báo đại một con số cho anh.', 10, '2026-10-16T10:39:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1eb13e27209c417a9ddb6662c7c1facf', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Anh đang dự tính khoảng bao nhiêu để đổi xe?', 11, '2026-10-16T10:42:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cf38e39869c240fe8fbe1c2761889197', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Tầm 1 tỷ đổ lại. Nhưng xe cũ anh chưa bán. Chắc phải bán Tucson trước.', 12, '2026-10-16T10:45:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2110ca8d6c6341f696a7ca7f073a7a3e', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Thế thì mình chưa cần vội đâu anh. Anh có thể qua xem và lái thử VF 8 trước, thấy hợp rồi mình tính tiếp chuyện bán xe cũ.', 13, '2026-10-16T10:48:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5437e3704c17464693d5d81789fe7ae1', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Anh ngại nhất là xe điện đi xa ấy. Nhà anh thỉnh thoảng về Thanh Hóa, có lúc đi Nghệ An nữa.', 14, '2026-10-16T10:51:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a866cfd8f9454a90ac8c51c5b99e47ad', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Anh thường đi một mạch hay có dừng nghỉ giữa đường?', 15, '2026-10-16T10:54:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('34fea98605df458c8e6b49f1698887ba', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Thường chạy một mạch, có mệt thì nghỉ. Xe xăng thích thì tạt vào đổ, 5 phút là xong.', 16, '2026-10-16T10:57:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('982a84542e9a4622be27096b42daffc5', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Đấy đúng là điểm xe xăng tiện hơn anh ạ. Xe điện đi xa thì phải tính điểm sạc trước, nhất là dịp lễ đông người. VF 8 đi cao tốc được nhưng em không muốn nói với anh là sẽ thoải mái như đổ xăng.', 17, '2026-10-16T11:00:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9e00dada855a439eb8533f6a7f32305f', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Thế nói thật thì đi Nghệ An có bất tiện không?', 18, '2026-10-16T11:03:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('caf0456f350d47b7817cbcb6ef94ccfe', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Có thể bất tiện nếu anh quen chạy liên tục và không muốn dừng lâu. Còn nếu nhà mình thường nghỉ ăn uống giữa đường thì có thể tranh thủ sạc.', 19, '2026-10-16T11:06:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cac8ac019f214cd3a74527389e5c9190', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Nhưng để chắc chắn, mình vẫn phải kiểm tra trạm sạc trên đúng tuyến anh hay đi, chứ em không dám khẳng định chặng nào cũng có trụ trống.', 20, '2026-10-16T11:09:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5b6e68c9259a460da6613fc672b0edd4', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Anh thấy có người bảo ra trạm sạc phải xếp hàng, có người còn gặp trụ hỏng.', 21, '2026-10-16T11:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e7cc8debccee4a94a05bd7262bf943bd', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Có trường hợp như vậy anh. Em cũng không phủ nhận.', 22, '2026-10-16T11:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8aa5893878634696ba4f634960019efa', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Điểm sạc nhiều không có nghĩa là lúc nào cũng sạc được ngay. Nên nếu anh đi xa liên tục thì đây là cái mình cần cân nhắc thật.', 23, '2026-10-16T11:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('13dcd79be48341f7b7e148bf9aab04de', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Nghe em nói thế thì chắc anh giữ Tucson cho lành. Haha.', 24, '2026-10-16T11:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fb4c8f8ed89742f68ae9fed59ff519b4', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Haha, nếu ưu tiên số một là đi xa không phải nghĩ chuyện sạc thì Tucson vẫn rất ổn anh ạ.', 25, '2026-10-16T11:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1b982702e54241f8976b6cf8fa9bc9fb', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Nhưng em nghĩ anh nên thử VF 8 một lần. Chạy thử sẽ thấy rõ sự khác biệt về độ êm, tăng tốc và cảm giác lái. Còn chuyện có đổi hay không thì tính sau.', 26, '2026-10-16T11:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('20c73ba3a6ff4fad91be967ebe061718', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Thế pin VF 8 dùng vài năm có chai nhiều không? Anh sợ chạy 4–5 năm lại phải thay pin, lúc đấy chắc tốn lắm.', 27, '2026-10-16T11:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('24bf23f733c64ec5a37f05ea2cbaceea', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Pin sẽ xuống cấp theo thời gian, cái đó là bình thường anh. Nhưng không phải cứ 4–5 năm là phải thay.', 28, '2026-10-16T11:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cf4daab2993d4be290c972a090d78d28', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Xe có chính sách bảo hành pin riêng, nếu gặp vấn đề đủ điều kiện thì sẽ được xử lý theo chính sách. Còn mức chai pin thực tế phụ thuộc vào cách sử dụng, số chu kỳ sạc và nhiều yếu tố khác.', 29, '2026-10-16T11:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3107c0dba007491bb76233e855646d7f', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Bảo hành pin bao lâu em?', 30, '2026-10-16T11:39:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8370804f0a36438284e36441b17e7ff1', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Em sẽ gửi anh đúng điều khoản bảo hành của phiên bản VF 8 mình chọn, kể cả điều kiện về dung lượng pin. Phần này cần đọc kỹ chứ không chỉ nhìn mỗi số năm bảo hành.', 31, '2026-10-16T11:42:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('508dd2d779204e0fba3f9c7320d2d4be', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Ừ, cái đấy quan trọng. Anh mua xe xác định đi 7–8 năm chứ không đổi liên tục.', 32, '2026-10-16T11:45:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cfa755e8e5bc48c6b6dec1f8d08d5f0d', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Thế thì càng nên xem kỹ phần pin và hậu mãi. À nhà anh có chỗ đỗ xe cố định không?', 33, '2026-10-16T11:48:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1a1c97eaf26b4e0ab401a7b8512ede7d', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Có, nhà đất. Sân đủ để 2 xe.', 34, '2026-10-16T11:51:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ad118b38726147489ec0166cfad899fc', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Vậy chuyện sạc hằng ngày dễ giải quyết hơn nhiều. Nếu hệ thống điện phù hợp và được lắp bộ sạc tại nhà thì đi làm về cắm sạc khá tiện.', 35, '2026-10-16T11:54:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('797ca25998804633b52c1ffe5e5e9db3', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Nhưng sạc ở nhà có nguy hiểm không em? Anh thấy báo đăng cháy xe điện suốt.', 36, '2026-10-16T11:57:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('eae80370dc1b40ba86b8ebb15345c2e4', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Cái này phải phân biệt nguyên nhân cụ thể anh ạ. Không phải cứ cháy liên quan đến điện là do pin xe.', 37, '2026-10-16T12:00:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0bd1a5e8cc6644ce8e3dd2e899e94e96', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Nhưng sạc điện vẫn cần đảm bảo an toàn. Khi lắp bộ sạc phải khảo sát nguồn điện, dây dẫn, thiết bị bảo vệ và vị trí lắp đặt. Không nên tự kéo ổ cắm linh tinh để sạc.', 38, '2026-10-16T12:03:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e46d7346354247369f8a5ed2290d0f3b', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Ừ. Thế xe này bảo dưỡng có tốn không? Tucson anh cứ 5.000–10.000 km lại đi bảo dưỡng.', 39, '2026-10-16T12:06:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a3ac77e55323403aa0c3833f91a04bf4', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Xe điện không có thay dầu động cơ như xe xăng nên giảm được một số hạng mục. Nhưng vẫn phải kiểm tra phanh, lốp, điều hòa, hệ thống điện và các phần khác theo lịch của hãng.', 40, '2026-10-16T12:09:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('76b5f34d6cf94c8f95f084358ed2eb23', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Chi phí cụ thể còn tùy tình trạng xe, chứ không phải xe điện là không tốn tiền bảo dưỡng anh nhé.', 41, '2026-10-16T12:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('608339102a124c8a94e205689ddcc53e', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Nghe cũng hợp lý. Nhưng anh còn nghe VF 8 trước đây lỗi phần mềm khá nhiều.', 42, '2026-10-16T12:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('246677c9359d4743a8439290449ad731', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Những phản ánh về phần mềm là điều anh nên tìm hiểu. Em không thể đảm bảo một chiếc xe không bao giờ phát sinh lỗi.', 43, '2026-10-16T12:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b748b7deb65d4f2fbed6ccf87478198c', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Em có thể cho anh xem xe đời hiện tại, phiên bản phần mềm và lịch sử bảo dưỡng nếu là xe trưng bày hoặc xe lái thử. Anh cứ dùng thử các tính năng trực tiếp, có gì chưa ổn mình trao đổi luôn.', 44, '2026-10-16T12:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3dcd89a6b0d04883906ca45b85a9442f', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Thế có lái thử đường dài được không? Chứ chạy một vòng showroom thì cũng không đánh giá được gì.', 45, '2026-10-16T12:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a460def956e9485ebf731c33fcba2db4', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Lái thử thông thường sẽ theo tuyến và thời lượng showroom sắp xếp. Em có thể hỏi bên phụ trách xem có hỗ trợ tuyến dài hơn không, nhưng chưa dám hứa trước với anh.', 46, '2026-10-16T12:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('317a7c10f30b4537a6b8a7650d386e58', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Anh muốn thử lên cầu, chạy đường lớn một chút. Xem cách âm với tăng tốc thế nào.', 47, '2026-10-16T12:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('85b8bdbd4dc54024972c440e5b1b41eb', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Được anh, em sẽ trao đổi đúng nhu cầu đó. Anh ở khu nào để em chọn điểm lái thử thuận tiện?', 48, '2026-10-16T12:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('72a69aac974c43d0a9c95d68099ecb52', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Anh ở Hà Đông.', 49, '2026-10-16T12:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('897987c0a9bc43e2bf5191e4424a9495', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Vậy em ưu tiên tìm điểm lái thử phía Hà Đông cho anh. Anh thường rảnh thứ Bảy hay Chủ nhật?', 50, '2026-10-16T12:39:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3d0295591e614c208038bdc856b6a756', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Sáng Chủ nhật được. Nhưng anh chưa có ý định cọc đâu nhé.', 51, '2026-10-16T12:42:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0789c1121d584e1885b97abd3721911c', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Vâng, chưa cần cọc gì cả anh. Mình cứ thử xe trước đã. Nếu chạy xong anh thấy không hợp thì cũng không sao.', 52, '2026-10-16T12:45:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5e63362e33f94fceab7a2444a6b59073', '54ae4a6deccd4eb1aeaa07372bc615c8', 'customer', 'Ok. Em gửi anh thêm thông tin bảo hành pin với bảng giá hiện tại nhé.', 53, '2026-10-16T12:48:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('60d7ed10a4cb41b7b80c3debd1adac7e', '54ae4a6deccd4eb1aeaa07372bc615c8', 'sales', 'Dạ được. Em gửi anh bảng giá theo phiên bản, điều kiện bảo hành và thông tin đăng ký lái thử để anh xem trước. Sau khi xác nhận được xe thử và khung giờ sáng Chủ nhật, em sẽ báo anh cụ thể.', 54, '2026-10-16T12:51:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f69d5bb9a57a4f9da3e0bab0381c01b8', '8788e91054e34a45ac86599d3baaf207', 'customer', 'Em ơi tư vấn giúp anh mẫu VF 5 Plus để chạy dịch vụ kết hợp gia đình với.', 1, '2026-10-16T16:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cc52587904db45d791601abc2384e6de', '8788e91054e34a45ac86599d3baaf207', 'sales', 'Dạ em chào anh Khánh! VF 5 Plus hiện đang là mẫu xe quốc dân cho anh em chạy dịch vụ kết hợp gia đình vì chi phí nhiên liệu và bảo dưỡng cực thấp ạ. Anh dự kiến mỗi ngày chạy khoảng bao nhiêu km ạ?', 2, '2026-10-16T16:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('290837530e974c68a45c40ef447de238', '8788e91054e34a45ac86599d3baaf207', 'customer', 'Anh định chạy Xanh SM Platform kết hợp chở khách quen đi sân bay, trung bình ngày khoảng 180 - 220 km.', 3, '2026-10-16T16:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8d54d70adaf4437e860371207fb58dc1', '8788e91054e34a45ac86599d3baaf207', 'sales', 'Dạ chạy tầm 200 km/ngày thì đi VF 5 tiết kiệm hơn xe xăng cỡ A/B khoảng 8-10 triệu tiền xăng mỗi tháng luôn anh ạ. Đặc biệt đang có chính sách miễn phí sạc tại trạm V-GREEN nên gần như anh không tốn chi phí nhiên liệu.', 4, '2026-10-16T17:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6e06289112a94026b48aec1934b37398', '8788e91054e34a45ac86599d3baaf207', 'customer', 'Anh đang gom vốn chỉ có sẵn tầm 140 triệu tiền mặt thôi, có đủ trả trước để lấy xe lăn bánh biển vàng không em?', 5, '2026-10-16T17:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a1cec1e3d80e486196b73eeec763257f', '8788e91054e34a45ac86599d3baaf207', 'sales', 'Dạ 140 triệu là hoàn toàn đủ anh nhé! Với VF 5 Plus mua kèm pin, ngân hàng hỗ trợ vay tối đa 80% giá trị xe trong 6-7 năm. Anh chỉ cần đối ứng khoảng 110-120 triệu tiền xe cộng thêm chi phí đăng ký biển số là nhận xe chạy ngay được ạ.', 6, '2026-10-16T17:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cc32177b931f409fa2860035145fcfcf', '8788e91054e34a45ac86599d3baaf207', 'customer', 'Thế mỗi tháng anh phải đóng ngân hàng khoảng bao nhiêu? Anh muốn tính kỹ xem trừ chi phí đi còn dư được bao nhiêu nuôi vợ con.', 7, '2026-10-16T17:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('de6e1baeec8a4438a97e95ed33224f69', '8788e91054e34a45ac86599d3baaf207', 'sales', 'Dạ nếu vay khoảng 400 triệu trong 6 năm (72 tháng) thì gốc cộng lãi mỗi tháng rơi vào khoảng 8,2 - 8,5 triệu đồng. Anh chạy đều 200 km/ngày thì chỉ khoảng 7-8 ngày doanh thu là đủ tiền trả góp cả tháng rồi ạ.', 8, '2026-10-16T17:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0d75d3166b7e4034ab39c8ae4380db95', '8788e91054e34a45ac86599d3baaf207', 'customer', 'Pin VF 5 sạc nhanh từ 20% lên 70% lúc anh nghỉ trưa mất bao lâu em?', 9, '2026-10-16T17:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('588ad9f522df44f9a7e0c0cdd41a8416', '8788e91054e34a45ac86599d3baaf207', 'sales', 'Dạ tại các trụ sạc nhanh DC từ 60 kW trở lên, anh cắm sạc từ 10% lên 70% chỉ mất khoảng 30 phút thôi ạ, vừa kịp lúc anh ăn trưa nghỉ ngơi là chạy tiếp ca chiều thoải mái.', 10, '2026-10-16T17:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('dd87b1f615c24d3cb42cfdc456dc68f2', '8788e91054e34a45ac86599d3baaf207', 'customer', 'Nhưng anh chưa có hợp đồng lao động vì làm tự do mấy năm nay, liệu ngân hàng có duyệt hồ sơ vay không?', 11, '2026-10-16T17:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5ace7a7afaa14a85b3e3b3ace26793c3', '8788e91054e34a45ac86599d3baaf207', 'sales', 'Dạ làm tự do hoặc chạy xe công nghệ vẫn làm hồ sơ vay bình thường anh nhé! Bên em có liên kết với VPBank và TPBank hỗ trợ duyệt qua sao kê tài khoản nhận tiền hàng ngày hoặc tài sản/lịch sử tín dụng CIC tốt, không bắt buộc hợp đồng lao động ạ.', 12, '2026-10-16T17:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f6c78980a5764a66aa3a13da1ca6f7cf', '8788e91054e34a45ac86599d3baaf207', 'customer', 'CIC của anh sạch, không nợ xấu. Đăng ký biển vàng với tham gia Xanh SM Platform thì bên em hỗ trợ làm trọn gói luôn chứ?', 13, '2026-10-16T17:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fbee9279e3b0451babc10aed4f6cca22', '8788e91054e34a45ac86599d3baaf207', 'sales', 'Dạ bên em hỗ trợ trọn gói từ bấm biển vàng, lắp thiết bị định vị hợp chuẩn, phù hiệu hợp tác xã cho đến kích hoạt tài khoản đối tác Xanh SM Platform luôn anh ạ.', 14, '2026-10-16T17:30:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8a1f56f9062e47df88392663a2e4de33', '8788e91054e34a45ac86599d3baaf207', 'customer', 'Tốt quá. Gửi cho anh danh sách giấy tờ cần chuẩn bị để chiều thứ Năm tuần này anh cầm qua showroom làm hồ sơ thẩm định vay trước nhé.', 15, '2026-10-16T17:33:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3fa2fe715ec94350b63f0f964941760d', '896a46aa394b41b18b3c12da5c8cd685', 'customer', 'Em ơi chị đang muốn mua chiếc xe đầu tiên trong đời, ngân sách tối đa cả đăng ký là 520 triệu thì lấy VF 5 ổn không hay cố lên VF 6?', 1, '2026-10-17T06:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0c7543b2ebf64836b512038b0cece8c5', '896a46aa394b41b18b3c12da5c8cd685', 'sales', 'Dạ em chào chị Trang! Nếu ngân sách trần của mình là 520 triệu đã bao gồm toàn bộ chi phí lăn bánh và không muốn vay thêm thì VF 5 Plus mua kèm pin là vừa khít và dư dả tài chính nhất chị ạ.', 2, '2026-10-17T06:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fe1c2b659b884b7f9c47e1abd2617900', '896a46aa394b41b18b3c12da5c8cd685', 'customer', 'VF 5 Plus lăn bánh biển Hà Nội bây giờ chính xác là bao nhiêu tiền em?', 3, '2026-10-17T06:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('96d6dd1f79204d818e9ce62854db853d', '896a46aa394b41b18b3c12da5c8cd685', 'sales', 'Dạ sau khi áp dụng ưu đãi hiện tại thì giá xe VF 5 Plus kèm pin cộng 20 triệu biển số Hà Nội và các phí đăng kiểm, bảo hiểm bắt buộc tổng cộng chỉ khoảng 505 - 512 triệu đồng thôi chị ạ!', 4, '2026-10-17T07:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2c5a9c6bb3c54b5eb2b5ff1883121253', '896a46aa394b41b18b3c12da5c8cd685', 'customer', 'Ôi thế là vừa đẹp trong khoản tiết kiệm 520 triệu của chị luôn. Chị mệnh Hỏa nên muốn tìm màu Đỏ hoặc màu Cam, bên em có những màu nào?', 5, '2026-10-17T07:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('20147be2c3cb431b9ebd6bcd9bdd4125', '896a46aa394b41b18b3c12da5c8cd685', 'sales', 'Dạ VF 5 có cả màu Đỏ tươi, Đỏ nóc trắng và màu Cam nóc trắng cực kỳ trẻ trung và hợp mệnh Hỏa luôn chị Trang ơi!', 6, '2026-10-17T07:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('75183cfce7db461a91259e3c410f2448', '896a46aa394b41b18b3c12da5c8cd685', 'customer', 'Chị ở chung cư Ngoại Giao Đoàn, mỗi ngày đi làm ở Duy Tân cả đi cả về khoảng 16 km. Nhưng chị chưa dùng xe điện bao giờ nên sợ lúc hết pin không biết thao tác cắm sạc có nặng tay không?', 7, '2026-10-17T07:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ef204348027c4e768c35297864b2d68c', '896a46aa394b41b18b3c12da5c8cd685', 'sales', 'Dạ súng sạc tại trạm V-GREEN thiết kế rất vừa tay, các chị em phụ nữ chỉ cần cắm vào cổng sạc trên xe và bấm xác nhận trên ứng dụng VinFast trong điện thoại là xe tự động sạc và tự ngắt khi đầy ạ.', 8, '2026-10-17T07:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f65beba4a1a742a1af62a06020940b23', '896a46aa394b41b18b3c12da5c8cd685', 'customer', 'Chi phí bảo dưỡng định kỳ của VF 5 so với Kia Sonet hay Raize thì thế nào em?', 9, '2026-10-17T07:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b7b0b8242a874f018417abff2c79eba1', '896a46aa394b41b18b3c12da5c8cd685', 'sales', 'Dạ xe điện không có dầu máy, bugi, lọc dầu hay hộp số nhiều cấp nên mốc bảo dưỡng của VF 5 là mỗi 12.000 km (thay vì 5.000 km như xe xăng), mỗi lần bảo dưỡng định kỳ chỉ hết khoảng 400.000 - 600.000 đồng thôi ạ.', 10, '2026-10-17T07:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('807d3ccb65fd4b8b9d10c8b7d966b8d9', '896a46aa394b41b18b3c12da5c8cd685', 'customer', 'Nghe thích thế! Thế trên VF 5 có cảnh báo điểm mù trên gương với cảnh báo phương tiện cắt ngang khi lùi không?', 11, '2026-10-17T07:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4e06747242ac46109259c6169b510e2a', '896a46aa394b41b18b3c12da5c8cd685', 'sales', 'Dạ có đầy đủ cả hai tính năng đó trên VF 5 Plus luôn chị ạ! Đây là điểm ăn tiền nhất của VF 5 so với các xe hạng A cùng tầm giá.', 12, '2026-10-17T07:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('448efdde82d24502ad1f35effa895130', '896a46aa394b41b18b3c12da5c8cd685', 'customer', 'Chụp ảnh thực tế chiếc màu Đỏ nóc trắng với màu Cam nóc trắng ở showroom gửi cho chị xem trước nhé, trưa mai tầm 12h15 nghỉ trưa ở Duy Tân chị chạy qua showroom xem xe.', 13, '2026-10-17T07:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f7cada4cf2d74935aa5d6ae8e602bcfe', '8b1161f1ef884671a14a953e48968757', 'sales', 'Em chào anh, em là Huy bên VinFast. Hôm trước em thấy anh có để lại thông tin quan tâm VF 8, không biết anh đã tham khảo xe ở đâu chưa ạ?', 1, '2026-10-12T16:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d26695439591483396985cbcc5af41e5', '8b1161f1ef884671a14a953e48968757', 'customer', 'Anh mới xem trên mạng thôi. Đang tính đổi xe mà vẫn hơi lăn tăn.', 2, '2026-10-12T16:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1a7392edfe7e46b9b41d1d8ab5c22fef', '8b1161f1ef884671a14a953e48968757', 'sales', 'Anh đang chạy xe gì vậy anh?', 3, '2026-10-12T16:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('34e8a1afd66a413c8a7ce6a6f50830c8', '8b1161f1ef884671a14a953e48968757', 'customer', 'Anh đang đi Tucson 2021. Xe cũng chưa có vấn đề gì, nhưng thấy mấy ông bạn chuyển qua xe điện nên anh muốn tìm hiểu thử.', 4, '2026-10-12T16:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('454f20c022514bb6a182f584e78f5332', '8b1161f1ef884671a14a953e48968757', 'sales', 'À Tucson thì xe cũng rộng và đi khá ổn rồi. Anh định đổi vì muốn tiết kiệm chi phí hay muốn trải nghiệm xe điện là chính?', 5, '2026-10-12T16:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7a0af331f64f4746aad9196a559786bd', '8b1161f1ef884671a14a953e48968757', 'customer', 'Cả hai. Nhưng chủ yếu muốn xe chạy êm, rộng rãi. Nhà anh 4 người, cuối tuần hay đi chơi.', 6, '2026-10-12T16:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6786e972250b4347acc1228047ef1edf', '8b1161f1ef884671a14a953e48968757', 'sales', 'Vậy VF 8 khá hợp đấy anh. Xe 5 chỗ, không gian rộng, đi gia đình thoải mái. Xe điện thì tăng tốc cũng bốc hơn Tucson khá nhiều.', 7, '2026-10-12T16:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2d651d1db16243e6b27dfb52b5ac8f8c', '8b1161f1ef884671a14a953e48968757', 'customer', 'Anh đã ngồi thử VF 8 bao giờ chưa?', 8, '2026-10-12T16:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('04991c8ba67140249194a1eaf4777bf3', '8b1161f1ef884671a14a953e48968757', 'customer', 'Chưa em. Mà VF 8 giờ giá thế nào?', 9, '2026-10-12T16:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c12487285e3b4067b5c28973d69e936e', '8b1161f1ef884671a14a953e48968757', 'sales', 'VF 8 có các phiên bản khác nhau nên giá sẽ chênh nhau anh nhé. Em chưa có bảng giá chốt theo xe tồn và ưu đãi hôm nay, nên em không báo đại một con số cho anh.', 10, '2026-10-12T16:52:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ccf10e8f9d2146fc8e1e8c775d469252', '8b1161f1ef884671a14a953e48968757', 'customer', 'Anh đang dự tính khoảng bao nhiêu để đổi xe?', 11, '2026-10-12T16:55:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('58070a8b1b9d481cb256de243cb1f24d', '8b1161f1ef884671a14a953e48968757', 'customer', 'Tầm 1 tỷ đổ lại. Nhưng xe cũ anh chưa bán. Chắc phải bán Tucson trước.', 12, '2026-10-12T16:58:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1405a62ce2d44b8482264271dc080d4d', '8b1161f1ef884671a14a953e48968757', 'sales', 'Thế thì mình chưa cần vội đâu anh. Anh có thể qua xem và lái thử VF 8 trước, thấy hợp rồi mình tính tiếp chuyện bán xe cũ.', 13, '2026-10-12T17:01:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b9ffe5e2652e437683b67be9d14235a5', '8b1161f1ef884671a14a953e48968757', 'customer', 'Anh ngại nhất là xe điện đi xa ấy. Nhà anh thỉnh thoảng về Thanh Hóa, có lúc đi Nghệ An nữa.', 14, '2026-10-12T17:04:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c9062bc02ba24cd59b6e3523f875e0b6', '8b1161f1ef884671a14a953e48968757', 'sales', 'Anh thường đi một mạch hay có dừng nghỉ giữa đường?', 15, '2026-10-12T17:07:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b1488b84f0b44eb19f8451273f489e8c', '8b1161f1ef884671a14a953e48968757', 'customer', 'Thường chạy một mạch, có mệt thì nghỉ. Xe xăng thích thì tạt vào đổ, 5 phút là xong.', 16, '2026-10-12T17:10:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('980425b4cff2400d85335bb16f640a62', '8b1161f1ef884671a14a953e48968757', 'sales', 'Đấy đúng là điểm xe xăng tiện hơn anh ạ. Xe điện đi xa thì phải tính điểm sạc trước, nhất là dịp lễ đông người. VF 8 đi cao tốc được nhưng em không muốn nói với anh là sẽ thoải mái như đổ xăng.', 17, '2026-10-12T17:13:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c5f85d55fb414559acb9f24a61b4ff35', '8b1161f1ef884671a14a953e48968757', 'customer', 'Thế nói thật thì đi Nghệ An có bất tiện không?', 18, '2026-10-12T17:16:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2831d2040e81482196aefb883c34ef3b', '8b1161f1ef884671a14a953e48968757', 'sales', 'Có thể bất tiện nếu anh quen chạy liên tục và không muốn dừng lâu. Còn nếu nhà mình thường nghỉ ăn uống giữa đường thì có thể tranh thủ sạc.', 19, '2026-10-12T17:19:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a4426ddece0c421dabf0cc5840b25967', '8b1161f1ef884671a14a953e48968757', 'sales', 'Nhưng để chắc chắn, mình vẫn phải kiểm tra trạm sạc trên đúng tuyến anh hay đi, chứ em không dám khẳng định chặng nào cũng có trụ trống.', 20, '2026-10-12T17:22:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('eb7ea4ce75aa48db85a517bce710140b', '8b1161f1ef884671a14a953e48968757', 'customer', 'Anh thấy có người bảo ra trạm sạc phải xếp hàng, có người còn gặp trụ hỏng.', 21, '2026-10-12T17:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2c4824acc013428887f87c8671d3e489', '8b1161f1ef884671a14a953e48968757', 'sales', 'Có trường hợp như vậy anh. Em cũng không phủ nhận.', 22, '2026-10-12T17:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5bd23e7f70d44f0db75f2455c1136bbf', '8b1161f1ef884671a14a953e48968757', 'customer', 'Điểm sạc nhiều không có nghĩa là lúc nào cũng sạc được ngay. Nên nếu anh đi xa liên tục thì đây là cái mình cần cân nhắc thật.', 23, '2026-10-12T17:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b5123c0ccc8349458aec1b7f835dd56f', '8b1161f1ef884671a14a953e48968757', 'customer', 'Nghe em nói thế thì chắc anh giữ Tucson cho lành. Haha.', 24, '2026-10-12T17:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0e66402f927249289d19fc296f329bb3', '8b1161f1ef884671a14a953e48968757', 'sales', 'Haha, nếu ưu tiên số một là đi xa không phải nghĩ chuyện sạc thì Tucson vẫn rất ổn anh ạ.', 25, '2026-10-12T17:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('94ba0689bdef416c9b11054d9c7a107c', '8b1161f1ef884671a14a953e48968757', 'sales', 'Nhưng em nghĩ anh nên thử VF 8 một lần. Chạy thử sẽ thấy rõ sự khác biệt về độ êm, tăng tốc và cảm giác lái. Còn chuyện có đổi hay không thì tính sau.', 26, '2026-10-12T17:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('680629e1bfd444e5910c619d2620c784', '8b1161f1ef884671a14a953e48968757', 'customer', 'Thế pin VF 8 dùng vài năm có chai nhiều không? Anh sợ chạy 4–5 năm lại phải thay pin, lúc đấy chắc tốn lắm.', 27, '2026-10-12T17:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7605507eb87a4509b69c0a53fcc6c0a9', '8b1161f1ef884671a14a953e48968757', 'sales', 'Pin sẽ xuống cấp theo thời gian, cái đó là bình thường anh. Nhưng không phải cứ 4–5 năm là phải thay.', 28, '2026-10-12T17:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e97f945d1eb247f19e92eb861aa54e08', '8b1161f1ef884671a14a953e48968757', 'customer', 'Xe có chính sách bảo hành pin riêng, nếu gặp vấn đề đủ điều kiện thì sẽ được xử lý theo chính sách. Còn mức chai pin thực tế phụ thuộc vào cách sử dụng, số chu kỳ sạc và nhiều yếu tố khác.', 29, '2026-10-12T17:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e37e35c0d7564835a70ce741720d9549', '8b1161f1ef884671a14a953e48968757', 'customer', 'Bảo hành pin bao lâu em?', 30, '2026-10-12T17:52:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('93a33baa115141b890b354dedc6853cb', '8b1161f1ef884671a14a953e48968757', 'sales', 'Em sẽ gửi anh đúng điều khoản bảo hành của phiên bản VF 8 mình chọn, kể cả điều kiện về dung lượng pin. Phần này cần đọc kỹ chứ không chỉ nhìn mỗi số năm bảo hành.', 31, '2026-10-12T17:55:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f6c7641a8c354cc28a37ec1f814abef3', '8b1161f1ef884671a14a953e48968757', 'customer', 'Ừ, cái đấy quan trọng. Anh mua xe xác định đi 7–8 năm chứ không đổi liên tục.', 32, '2026-10-12T17:58:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f2791d98a0c34570bbcc05234707f06b', '8b1161f1ef884671a14a953e48968757', 'sales', 'Thế thì càng nên xem kỹ phần pin và hậu mãi. À nhà anh có chỗ đỗ xe cố định không?', 33, '2026-10-12T18:01:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('364334a9d6684b32b68c371c55a0d98b', '8b1161f1ef884671a14a953e48968757', 'customer', 'Có, nhà đất. Sân đủ để 2 xe.', 34, '2026-10-12T18:04:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4ca5d25e819c4b438920cc8883dab6f3', '8b1161f1ef884671a14a953e48968757', 'sales', 'Vậy chuyện sạc hằng ngày dễ giải quyết hơn nhiều. Nếu hệ thống điện phù hợp và được lắp bộ sạc tại nhà thì đi làm về cắm sạc khá tiện.', 35, '2026-10-12T18:07:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8484ae46988249adaece21d65f335480', '8b1161f1ef884671a14a953e48968757', 'customer', 'Nhưng sạc ở nhà có nguy hiểm không em? Anh thấy báo đăng cháy xe điện suốt.', 36, '2026-10-12T18:10:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9e616dc6d77e499ba932556731ee3b75', '8b1161f1ef884671a14a953e48968757', 'sales', 'Cái này phải phân biệt nguyên nhân cụ thể anh ạ. Không phải cứ cháy liên quan đến điện là do pin xe.', 37, '2026-10-12T18:13:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('dbcb8b0630ec4862b5b348baa35f13d3', '8b1161f1ef884671a14a953e48968757', 'customer', 'Nhưng sạc điện vẫn cần đảm bảo an toàn. Khi lắp bộ sạc phải khảo sát nguồn điện, dây dẫn, thiết bị bảo vệ và vị trí lắp đặt. Không nên tự kéo ổ cắm linh tinh để sạc.', 38, '2026-10-12T18:16:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('41156ddcef7d4ad38d0f8bc33bdb6a38', '8b1161f1ef884671a14a953e48968757', 'customer', 'Ừ. Thế xe này bảo dưỡng có tốn không? Tucson anh cứ 5.000–10.000 km lại đi bảo dưỡng.', 39, '2026-10-12T18:19:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8e1c60e4804f40f8aeaa40016a48100e', '8b1161f1ef884671a14a953e48968757', 'sales', 'Xe điện không có thay dầu động cơ như xe xăng nên giảm được một số hạng mục. Nhưng vẫn phải kiểm tra phanh, lốp, điều hòa, hệ thống điện và các phần khác theo lịch của hãng.', 40, '2026-10-12T18:22:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('641b2efb136644b9a9929bfcd0400b52', '8b1161f1ef884671a14a953e48968757', 'customer', 'Chi phí cụ thể còn tùy tình trạng xe, chứ không phải xe điện là không tốn tiền bảo dưỡng anh nhé.', 41, '2026-10-12T18:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('50c745fd00e2414e967ef981e02e1116', '8b1161f1ef884671a14a953e48968757', 'customer', 'Nghe cũng hợp lý. Nhưng anh còn nghe VF 8 trước đây lỗi phần mềm khá nhiều.', 42, '2026-10-12T18:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b5a59d39205a49248b810ea163c26a61', '8b1161f1ef884671a14a953e48968757', 'sales', 'Những phản ánh về phần mềm là điều anh nên tìm hiểu. Em không thể đảm bảo một chiếc xe không bao giờ phát sinh lỗi.', 43, '2026-10-12T18:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fe24a15c089640efa5cd4baf3216975d', '8b1161f1ef884671a14a953e48968757', 'sales', 'Em có thể cho anh xem xe đời hiện tại, phiên bản phần mềm và lịch sử bảo dưỡng nếu là xe trưng bày hoặc xe lái thử. Anh cứ dùng thử các tính năng trực tiếp, có gì chưa ổn mình trao đổi luôn.', 44, '2026-10-12T18:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('16a8dea74d104088992213cbf9f5ce3b', '8b1161f1ef884671a14a953e48968757', 'customer', 'Thế có lái thử đường dài được không? Chứ chạy một vòng showroom thì cũng không đánh giá được gì.', 45, '2026-10-12T18:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7d9c13d2da99463195a28836f115ad20', '8b1161f1ef884671a14a953e48968757', 'sales', 'Lái thử thông thường sẽ theo tuyến và thời lượng showroom sắp xếp. Em có thể hỏi bên phụ trách xem có hỗ trợ tuyến dài hơn không, nhưng chưa dám hứa trước với anh.', 46, '2026-10-12T18:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('249c672c09cc4d64a41e63ce13334a6f', '8b1161f1ef884671a14a953e48968757', 'customer', 'Anh muốn thử lên cầu, chạy đường lớn một chút. Xem cách âm với tăng tốc thế nào.', 47, '2026-10-12T18:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a250b768ca4a408bb333da38edf15f8a', '8b1161f1ef884671a14a953e48968757', 'sales', 'Được anh, em sẽ trao đổi đúng nhu cầu đó. Anh ở khu nào để em chọn điểm lái thử thuận tiện?', 48, '2026-10-12T18:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9588963d0d354829a59d546a36e956f1', '8b1161f1ef884671a14a953e48968757', 'customer', 'Anh ở Hà Đông.', 49, '2026-10-12T18:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('99a4d18b18fe4016929bcc36dabe4568', '8b1161f1ef884671a14a953e48968757', 'sales', 'Vậy em ưu tiên tìm điểm lái thử phía Hà Đông cho anh. Anh thường rảnh thứ Bảy hay Chủ nhật?', 50, '2026-10-12T18:52:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('041bbb2e8b89468e9362bfae94bf7ff5', '8b1161f1ef884671a14a953e48968757', 'customer', 'Sáng Chủ nhật được. Nhưng anh chưa có ý định cọc đâu nhé.', 51, '2026-10-12T18:55:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('55ce127b3c604ac3b3748437a789e9be', '8b1161f1ef884671a14a953e48968757', 'sales', 'Vâng, chưa cần cọc gì cả anh. Mình cứ thử xe trước đã. Nếu chạy xong anh thấy không hợp thì cũng không sao.', 52, '2026-10-12T18:58:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8bc010ae36324c9487040acf96a861ac', '8b1161f1ef884671a14a953e48968757', 'customer', 'Ok. Em gửi anh thêm thông tin bảo hành pin với bảng giá hiện tại nhé.', 53, '2026-10-12T19:01:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f231c436375b48bb8527853424658ae5', '8b1161f1ef884671a14a953e48968757', 'sales', 'Dạ được. Em gửi anh bảng giá theo phiên bản, điều kiện bảo hành và thông tin đăng ký lái thử để anh xem trước. Sau khi xác nhận được xe thử và khung giờ sáng Chủ nhật, em sẽ báo anh cụ thể.', 54, '2026-10-12T19:04:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('077b60503d604e0aafda48953be5f708', '8b1161f1ef884671a14a953e48968757', 'sales', 'xin chao', 55, '2026-10-17T09:41:16.686433+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0729f97ca59e41eb997e6f9e64bd631d', 'a0986c545dd54d858afc2a406be2133f', 'sales', 'Dạ em chào anh Kiệt ạ! Em là Minh Anh bên VinFast. Em nhận được yêu cầu tư vấn dòng SUV 5 chỗ cỡ D VF 8 của anh, em xin phép hỗ trợ thông tin chi tiết tới anh ạ.', 1, '2026-10-16T20:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('074fc342453b4e20a0e05bd551dcfa1a', 'a0986c545dd54d858afc2a406be2133f', 'customer', 'Chào em, anh đang tìm hiểu VF 8 bản Lux Plus đời mới. Bản này so với VF 8 đời 2023 đã cải tiến hệ thống treo nhiều chưa em?', 2, '2026-10-16T20:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('85ce941bf9f44148bba8a1ac70b5e77d', 'a0986c545dd54d858afc2a406be2133f', 'sales', 'Dạ VF 8 Lux và Lux Plus đã được tinh chỉnh lại toàn bộ hệ thống giảm xóc và lò xo sau nên đi qua gờ giảm tốc êm và đầm chắc hơn hẳn bản đầu 2023 anh ạ. Ngoài ra xe còn tích hợp trợ lý ảo ViVi 2.0 có AI tạo sinh rất thông minh.', 3, '2026-10-16T20:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8954904318e5463b915826b6fc5943c9', 'a0986c545dd54d858afc2a406be2133f', 'customer', 'Anh đang phân vân giữa VF 8 Lux Plus với Hyundai SantaFe bản Prestige. Gia đình anh 4 người hay đi du lịch đường dài Tây Bắc như Mộc Châu, Sapa.', 4, '2026-10-16T21:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d2a2ddbbc8c14fee92b724ef762bd22f', 'a0986c545dd54d858afc2a406be2133f', 'sales', 'Dạ nếu anh hay đi đèo núi Tây Bắc thì VF 8 Lux Plus có lợi thế cực lớn anh ạ: dẫn động 2 cầu toàn thời gian AWD công suất 402 mã lực, mô-men xoắn tức thời 620 Nm giúp vượt xe trên đèo cực kỳ dứt khoát, và khi đổ đèo có phanh tái sinh vừa giữ tốc độ an toàn vừa nạp lại pin.', 5, '2026-10-16T21:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('627ed24c9ef44736a67c82702bfa9a69', 'a0986c545dd54d858afc2a406be2133f', 'customer', 'Đi lên Sapa hay Mộc Châu mùa đông bật sưởi thì pin có tụt nhanh không? Và trên đó trạm sạc có sẵn không em?', 6, '2026-10-16T21:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7ffc493ce2284b5aafd579a070cdef9d', 'a0986c545dd54d858afc2a406be2133f', 'sales', 'Dạ VF 8 Lux Plus có sưởi ghế và sưởi vô-lăng nên đi mùa đông rất tiết kiệm điện hơn chỉ bật điều hòa nóng toàn khoang. Tuyến cao tốc Nội Bài - Lào Cai hay quốc lộ 6 đi Mộc Châu đều có trạm sạc nhanh V-GREEN ở các trạm dừng nghỉ và ngay trung tâm thị xã Sapa, Mộc Châu luôn ạ.', 7, '2026-10-16T21:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c4ad3ad630b746049213d36214dd0de2', 'a0986c545dd54d858afc2a406be2133f', 'customer', 'Giá lăn bánh bản VF 8 Lux Plus mua luôn pin bây giờ sau hết các chương trình ưu đãi là bao nhiêu em?', 8, '2026-10-16T21:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ffeadd5e0e7b49f8a50f76cf7c31f96f', 'a0986c545dd54d858afc2a406be2133f', 'sales', 'Dạ sau khi áp dụng ưu đãi hiện hành và miễn 100% lệ phí trước bạ, giá lăn bánh VF 8 Lux Plus kèm pin tại Hà Nội rơi vào khoảng 1 tỷ 240 triệu đến 1 tỷ 260 triệu tùy phương án ưu đãi anh chọn ạ.', 9, '2026-10-16T21:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c8b77a3452be4c679e2cdc7922cbcaf8', 'a0986c545dd54d858afc2a406be2133f', 'customer', 'Anh mua đứng tên công ty của anh để lấy hóa đơn VAT khấu trừ thuế thì thủ tục có khác cá nhân không?', 10, '2026-10-16T21:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d93ef1e057f1413e829a29f9ef08317f', 'a0986c545dd54d858afc2a406be2133f', 'sales', 'Dạ mua đứng tên doanh nghiệp rất nhanh gọn anh ạ, bên em xuất hóa đơn VAT 100% theo giá trị xe để công ty mình khấu trừ thuế GTGT và hạch toán chi phí tài sản cố định.', 11, '2026-10-16T21:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b1e2fac860a04d7d8745e9a24446c53e', 'a0986c545dd54d858afc2a406be2133f', 'customer', 'Công ty anh thanh toán chuyển khoản 100% không vay ngân hàng. Màu sơn phối 2 màu của bản Lux có những tông nào đẹp em?', 12, '2026-10-16T21:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ee81b2546fd24cefa2888bab4ab572d9', 'a0986c545dd54d858afc2a406be2133f', 'sales', 'Dạ bản Lux có các phối màu 2 tông rất sang trọng như Đen - Bạc, Xanh rêu - Bạc, hoặc Đỏ - Bạc anh ạ. Hiện tại bên em đang có sẵn mẫu trưng bày phối màu Xanh - Bạc ở showroom.', 13, '2026-10-16T21:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e9990c0247a748aa97d1a5f6b2d65662', 'a0986c545dd54d858afc2a406be2133f', 'customer', 'Gửi cho anh báo giá đóng dấu đỏ cho pháp nhân công ty và danh mục hồ sơ xuất hóa đơn công ty qua đây nhé, chiều thứ Sáu lúc 15h anh ghé xem xe thực tế.', 14, '2026-10-16T21:30:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ee06d90279544819b14c3298d3053198', 'a6b7f8a483a4455c9b2d4799d920973e', 'customer', 'Chào em, chị đang ở Times City, muốn tìm hiểu mẫu VF 6 Plus màu xanh rêu hoặc màu trắng.', 1, '2026-10-17T11:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ffe29ba30f5e4e6f9af98fdc5b90cc08', 'a6b7f8a483a4455c9b2d4799d920973e', 'sales', 'Dạ em chào chị Linh ạ! Cư dân Times City đi xe điện VinFast cực kỳ đông vì hệ thống trạm sạc dưới hầm rất nhiều và có chính sách hỗ trợ gửi xe, sạc điện rất tốt ạ.', 2, '2026-10-17T11:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e384de05eef64a0fbd569dec88fcd4ed', 'a6b7f8a483a4455c9b2d4799d920973e', 'customer', 'Đúng rồi em, chị thấy hàng xóm tầng chị đổi sang VF 6 khen đi phố nhẹ nhàng lắm. Nhưng chị muốn hỏi kỹ về các tính năng an toàn hỗ trợ lái vì chị hay đi cao tốc Hà Nội - Hải Phòng về thăm bố mẹ.', 3, '2026-10-17T11:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c9e0620f58c748b7b32046f8819759d2', 'a6b7f8a483a4455c9b2d4799d920973e', 'sales', 'Dạ chị đi cao tốc Hà Nội - Hải Phòng bằng VF 6 Plus thì nhàn tênh luôn chị ạ! Xe có Kiểm soát hành trình thích ứng (ACC), Hỗ trợ giữ làn đường, Hỗ trợ di chuyển khi ùn tắc, Tự động phanh khẩn cấp và Hiển thị thông tin lên kính lái HUD.', 4, '2026-10-17T12:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1e1d27bb5a5f42e48736e30eea0729c9', 'a6b7f8a483a4455c9b2d4799d920973e', 'customer', 'Đi từ Times City xuống trung tâm TP Hải Phòng khoảng 110 km, chạy tốc độ 100 - 120 km/h trên cao tốc thì đi về trong ngày có cần sạc ở Hải Phòng không?', 5, '2026-10-17T12:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ddbde6d06c39461cbb9fe06ad4d8ce1c', 'a6b7f8a483a4455c9b2d4799d920973e', 'sales', 'Dạ khứ hồi Hà Nội - Hải Phòng khoảng 220 km, trong khi VF 6 Plus sạc đầy 100% đi cao tốc thực tế vẫn đạt khoảng 330 - 350 km nên chị đi về trong ngày vẫn còn dư khoảng 30% pin, không bắt buộc phải sạc ở Hải Phòng đâu ạ.', 6, '2026-10-17T12:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3e508284c424413596227ad614851aa8', 'a6b7f8a483a4455c9b2d4799d920973e', 'customer', 'Thế thì yên tâm hẳn. Chị đang có chiếc Kia Morning đời 2019 biển Hà Nội đi được 4 vạn km, muốn đổi sang VF 6 Plus thì bên em định giá khoảng bao nhiêu?', 7, '2026-10-17T12:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d0f1081aead941eb9cb8deee9e6424e5', 'a6b7f8a483a4455c9b2d4799d920973e', 'sales', 'Dạ Morning 2019 chạy 4 vạn km giữ gìn đẹp thì bên bộ phận Thu cũ Đổi mới sẽ kiểm tra thực tế và trả giá rất sát thị trường, đồng thời chị được hưởng thêm mức hỗ trợ đổi xe xăng sang xe điện của hãng nữa ạ.', 8, '2026-10-17T12:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7d916218977740108610b3c785d6f247', 'a6b7f8a483a4455c9b2d4799d920973e', 'customer', 'Sau khi trừ tiền bán xe cũ đi, phần còn lại chị trả thẳng bằng tiền mặt luôn, không vay ngân hàng.', 9, '2026-10-17T12:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6adfdd01326b4e41b53f2f8b925bf3fc', 'a6b7f8a483a4455c9b2d4799d920973e', 'sales', 'Dạ nếu trả thẳng thì thủ tục cực nhanh, bên em có thể làm song song việc thu xe cũ và xuất hóa đơn bấm biển xe mới trong vòng 2-3 ngày làm việc thôi ạ.', 10, '2026-10-17T12:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d47f1e1eface4b37a6ecba76ecd45070', 'a6b7f8a483a4455c9b2d4799d920973e', 'customer', 'Hiện tại màu Trắng nội thất Nâu Moca bản VF 6 Plus có xe giao ngay trong tuần sau không em?', 11, '2026-10-17T12:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0bde85301a124837ab2b0cf5aeecfba4', 'a6b7f8a483a4455c9b2d4799d920973e', 'sales', 'Dạ bên em đang có đúng 1 suất VF 6 Plus Trắng - Nâu Moca vừa về kho đại lý sáng nay chị ạ!', 12, '2026-10-17T12:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('166718f33aaf49179feff7a056189787', 'a6b7f8a483a4455c9b2d4799d920973e', 'customer', 'Vậy chiều mai thứ Năm lúc 16h30 chị chạy chiếc Morning qua showroom để bên em thẩm định giá xe cũ và chị xem trực tiếp chiếc VF 6 Trắng nội thất Nâu luôn nhé.', 13, '2026-10-17T12:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('dc92094904a04069bac3a2a9d9e63914', 'b75f49c4336b48b5864127b632df8e48', 'customer', 'Alo em, anh đang tìm hiểu VF 8 bản Eco để chạy công việc hàng ngày đi các khu công nghiệp Bắc Ninh, Bắc Giang, Hải Dương.', 1, '2026-10-17T14:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9cacce3ec401459584fdf4d3f9c2b1f7', 'b75f49c4336b48b5864127b632df8e48', 'sales', 'Dạ em chào anh Đạt! Anh hay đi công tác các khu công nghiệp Bắc Ninh, Bắc Giang, Hải Dương từ Long Biên thì VF 8 Eco là lựa chọn cực kỳ kinh tế và an toàn trên quốc lộ 1A, quốc lộ 5 luôn ạ.', 2, '2026-10-17T14:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ef88911cbdb448a09c9a7c337aefe293', 'b75f49c4336b48b5864127b632df8e48', 'customer', 'Trung bình mỗi tháng anh đi khoảng 3.000 - 3.500 km. Hiện anh đang đi Honda CR-V xăng mỗi tháng tốn gần 8 triệu tiền xăng nên muốn chuyển sang xe điện.', 3, '2026-10-17T14:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5eb37c1bf5214029a9cc0ccf197ac45b', 'b75f49c4336b48b5864127b632df8e48', 'sales', 'Dạ đi 3.500 km/tháng mà chuyển từ CR-V sang VF 8 Eco thì mỗi năm anh tiết kiệm được gần 90 - 100 triệu tiền nhiên liệu và bảo dưỡng đấy anh ạ!', 4, '2026-10-17T15:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('06c3044b366d4e3596984bda8206b0d8', 'b75f49c4336b48b5864127b632df8e48', 'customer', 'Bản VF 8 Eco đời mới hiện nay một lần sạc đầy đi thực tế được bao nhiêu km? Anh sợ ngày chạy 250 km qua nhiều tỉnh phải dừng sạc lâu.', 5, '2026-10-17T15:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9e85c4e9c4e445feaed32eb70a893abe', 'b75f49c4336b48b5864127b632df8e48', 'sales', 'Dạ VF 8 bản S/Eco trang bị pin CATL đi được tới 471 km theo chuẩn WLTP, thực tế chạy đường trường đạt khoảng 400 - 420 km/lần sạc đầy. Anh đi 250 km/ngày từ sáng đến tối về nhà ở Long Biên vẫn còn dư hơn 35% pin, hoàn toàn không cần dừng sạc dọc đường ạ.', 6, '2026-10-17T15:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cedd437de0ba4da4b046aeddb7439189', 'b75f49c4336b48b5864127b632df8e48', 'customer', 'Giá lăn bánh VF 8 Eco mua kèm pin tại Hà Nội tháng này tốt nhất là bao nhiêu em?', 7, '2026-10-17T15:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('25f9ad4c989e4d48815da5445e9a48db', 'b75f49c4336b48b5864127b632df8e48', 'sales', 'Dạ VF 8 bản S/Eco kèm pin sau khi trừ hết ưu đãi tiền mặt và quà tặng quy đổi hiện tại thì giá lăn bánh biển Hà Nội chỉ khoảng 1 tỷ 060 triệu đến 1 tỷ 080 triệu thôi anh ạ, ngang ngửa một chiếc C-SUV máy xăng.', 8, '2026-10-17T15:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('33b01276884748988e8dac30a944ebee', 'b75f49c4336b48b5864127b632df8e48', 'customer', 'Bản Eco có gói hỗ trợ lái ADAS trên cao tốc không em? Anh chạy cao tốc Hà Nội - Bắc Giang suốt nên rất cần giữ khoảng cách và giữ làn.', 9, '2026-10-17T15:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('256fe156b4024487a831f19228ca04a0', 'b75f49c4336b48b5864127b632df8e48', 'sales', 'Dạ có đầy đủ anh Đạt ơi! Cả bản Eco vẫn được trang bị gói ADAS với Ga tự động thích ứng ACC, Hỗ trợ giữ làn, Cảnh báo lệch làn, Cảnh báo điểm mù và Phanh tự động khẩn cấp ạ.', 10, '2026-10-17T15:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('57f8f334401f4650ae1f7123a65d09ef', 'b75f49c4336b48b5864127b632df8e48', 'customer', 'Anh muốn đổi luôn chiếc CR-V đời 2020 của anh sang VF 8 Eco màu Đen, phần chênh anh bù tiền mặt luôn.', 11, '2026-10-17T15:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7cf08851bf1b4a938e18fda00513d9f6', 'b75f49c4336b48b5864127b632df8e48', 'sales', 'Dạ CR-V 2020 giữ giá rất tốt, anh đổi qua chương trình Thu cũ Đổi mới chỉ cần bù thêm một khoản nhỏ là lấy VF 8 Eco mới tinh luôn ạ. Sáng thứ Sáu tuần này khoảng 9h00 anh có rảnh ghé qua showroom hoặc để em cùng chuyên viên thẩm định qua Long Biên xem xe giúp anh không ạ?', 12, '2026-10-17T15:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2ff5687ca4e349c3ab03e2a07aeb790b', 'b75f49c4336b48b5864127b632df8e48', 'customer', 'Sáng thứ Sáu 9h00 em cho bên thẩm định qua nhà anh ở khu Việt Hưng, Long Biên xem xe CR-V luôn nhé, tiện mang hợp đồng mẫu VF 8 Eco qua cho anh xem.', 13, '2026-10-17T15:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e94041eb15ff4846a1362cf568e5968a', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Em ơi, VF 3 giờ giá bao nhiêu nhỉ?', 1, '2026-10-12T22:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ee5bf4f663ed4514a716bf1bf3d7c8c7', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Dạ, VF 3 Eco giá niêm yết tham khảo từ 285 triệu, còn bản Plus từ 296 triệu anh nhé. Anh đang muốn lấy xe luôn hay mới tìm hiểu thôi?', 2, '2026-10-12T22:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7644adc61fc24309b8b58dbdee052aff', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Anh đang xem thôi. Tầm này mua VF 3 ổn không em? Anh thấy ngoài đường chạy nhiều phết.', 3, '2026-10-12T22:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1124cbc62c8d43d3827284f1ef325fc4', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Nếu chủ yếu đi trong phố thì ổn anh. Xe nhỏ, dễ luồn lách, đỗ xe cũng tiện. Nhưng VF 3 chỉ có 4 chỗ nên nếu nhà mình đông người thì hơi hạn chế.', 4, '2026-10-12T22:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9c8117c137bc44bd9944306706f12cf8', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Nhà anh 3 người, hai vợ chồng với đứa nhỏ 4 tuổi.', 5, '2026-10-12T22:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e720d49822d54405b032bff28acd06e6', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Vậy vẫn dùng được anh. Nhưng em hỏi thêm, nhà mình có hay về quê hoặc đi chơi xa không?', 6, '2026-10-12T22:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('757029b48ee7491ebd38c3ce4258377b', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Có chứ, tháng chắc về Bắc Ninh 1–2 lần. Còn lại anh đi làm ở Cầu Giấy, nhà ở Nam Từ Liêm.', 7, '2026-10-12T22:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2e482b7d1c2042d3b813d42fc5e4774a', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Quãng đường như thế VF 3 đáp ứng được. Nhưng vì anh có con nhỏ nên em nghĩ anh nên xem cả VF 5 nữa, xe 5 chỗ, không gian và cốp thoải mái hơn.', 8, '2026-10-12T22:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fa208fe0fd94436ab3967fec0e690ac5', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'VF 5 tận gần 500 triệu mà em. Anh cố lắm chắc chỉ có 150 triệu tiền mặt thôi.', 9, '2026-10-12T22:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5d7b752157d94e57bb24c10363108a51', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'À, vậy anh đang tính vay ngân hàng phần còn lại đúng không?', 10, '2026-10-12T22:52:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('608e954383d346aaadafb872d0e4e81b', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Ừ. Nhưng mỗi tháng trả tầm 5 triệu đổ lại thôi. Cao quá thì mệt.', 11, '2026-10-12T22:55:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('01b5355cea5e41ccac2fae7d3f420da6', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Nếu giới hạn 5 triệu/tháng thì em nghĩ nên tính kỹ, vì ngoài tiền vay còn gửi xe, bảo hiểm và các chi phí sử dụng khác.', 12, '2026-10-12T22:58:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1060235c908b493686b4884850e2047c', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Anh đang muốn trả góp trong mấy năm?', 13, '2026-10-12T23:01:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('406ed499e361474a9453276fed84778b', 'be77752496eb4fb5b95889ba203e97e2', 'customer', '5 năm đi. Anh không muốn vay lâu quá.', 14, '2026-10-12T23:04:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7a0a6a1799084adf942bb5ce0d2e9dce', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Em tính sơ bộ để anh hình dung nhé. Giả sử mua VF 3 khoảng 285 triệu, mình có sẵn 150 triệu và vay 135 triệu trong 5 năm.', 15, '2026-10-12T23:07:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e48a9c7b88344faf977fa24e01eee2df', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Nếu giả định lãi 9%/năm, trả gốc đều hằng tháng, tháng đầu khoảng 3,26 triệu, các tháng sau giảm dần. Đây chỉ là ví dụ, chưa phải phương án được ngân hàng duyệt.', 16, '2026-10-12T23:10:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d3297cb2d6fc4b89b93b2ed94e725c13', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Ơ anh tưởng trả góp là tháng nào cũng bằng nhau chứ?', 17, '2026-10-12T23:13:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5cfe69ba750d4453bdd2be4b2c4bd5e5', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Có nhiều cách trả anh. Ví dụ trả gốc đều thì tổng tiền giảm dần, còn trả số tiền tương đối cố định thì ngân hàng sẽ tính theo phương thức khác.', 18, '2026-10-12T23:16:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('adb89f45b2ed4366925f5b782f858064', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Khi có phương án cụ thể em sẽ gửi anh cả lịch trả nợ, không chỉ báo mỗi số tiền tháng đầu.', 19, '2026-10-12T23:19:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9a925b73387e477b8aee0ea3c2839607', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Thế nếu anh vay 200 triệu để giữ lại ít tiền phòng thân thì sao?', 20, '2026-10-12T23:22:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4a4ce06ee6524647abdd36cd03b5d593', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Vẫn có thể tính thử anh. Với cùng giả định 9%/năm và 60 tháng, vay 200 triệu thì tháng đầu khoảng 4,83 triệu theo cách trả gốc đều.', 21, '2026-10-12T23:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c1ef9b7b00b7400296225e93e53c8e19', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Nhưng số đó chưa gồm phí khác, và lãi suất thực tế có thể thay đổi sau thời gian ưu đãi.', 22, '2026-10-12T23:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('318c7cbbf225434c8ef6822eacbbe04f', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Nghe cũng vừa. Nhưng anh không thích kiểu ban đầu lãi thấp xong sau tăng lên đâu.', 23, '2026-10-12T23:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ca28f91bc36c42738396801f9a5c97aa', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Vâng, cái đó phải hỏi rõ từ đầu. Em sẽ ưu tiên phương án có thông tin minh bạch về lãi sau ưu đãi, phí trả trước hạn và tổng tiền phải trả. Chứ chỉ nhìn lãi suất năm đầu thì dễ hiểu nhầm lắm.', 24, '2026-10-12T23:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d3838424ebeb4d7a870e1e684d45fd61', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Mà VF 3 bé thế, đi cao tốc có ổn không? Thấy xe trông như đồ chơi ấy.', 25, '2026-10-12T23:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f6461dffe9ef4da687c8c84765c15c5f', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Haha, nhiều khách nhìn ảnh cũng nói vậy anh. Xe nhỏ thật, không phải kiểu rộng rãi như SUV thông thường.', 26, '2026-10-12T23:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('60b119c80f3b486397a9e1b646179419', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'VF 3 vẫn có thể sử dụng trên những tuyến đường được phép và phù hợp điều kiện vận hành. Nhưng nếu anh thường xuyên chạy cao tốc, chở cả nhà và nhiều đồ thì VF 5 hợp hơn.', 27, '2026-10-12T23:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ee84ce3b907940c39722aec60294ba98', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Thế tại sao lúc đầu em bảo VF 3 ổn?', 28, '2026-10-12T23:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('22eaf6d3bb7141039171c91d6ec20c78', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Vì ban đầu em hiểu anh chủ yếu đi làm trong phố và có ngân sách giới hạn. Với nhu cầu đó VF 3 là lựa chọn hợp lý về chi phí.', 29, '2026-10-12T23:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b62f0d903c484bd7b26c999b4c3df4c0', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Nhưng nếu anh đặt nặng chuyện đi xa và sự thoải mái của cả gia đình thì em sẽ nghiêng về VF 5 hơn. Hai mẫu phục vụ nhu cầu hơi khác nhau.', 30, '2026-10-12T23:52:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5e8ff0fa79a84db3bdbdd1be95940bb5', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'VF 5 hơn VF 3 những gì đáng tiền?', 31, '2026-10-12T23:55:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('121c626f10bf4632a47a40d2ee9bb2b8', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Dễ thấy nhất là VF 5 có 5 chỗ ngồi, khoang hành lý thực dụng hơn và kích thước lớn hơn. Công suất cũng cao hơn đáng kể.', 32, '2026-10-12T23:58:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('43a40ee389664e3381a82179de06a486', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Về pin, VF 3 có quãng đường công bố khoảng 215 km còn VF 5 khoảng 326 km mỗi lần sạc theo NEDC. Đi thực tế sẽ tùy điều kiện.', 33, '2026-10-13T00:01:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d4d583388fca4d1589820c19918d10fe', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Thế chênh gần 200 triệu, anh thấy không đáng lắm.', 34, '2026-10-13T00:04:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2f59c90c55da457ba917a2e431b241b0', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Nếu tính riêng tiền mua xe thì đúng là chênh nhiều anh. Em cũng không nghĩ ai mua VF 3 cũng nên cố lên VF 5.', 35, '2026-10-13T00:07:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0b9a1154d53d4114ad98d57e84fe55d4', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Với 150 triệu sẵn có thì VF 3 nhẹ gánh tài chính hơn hẳn. VF 5 chỉ đáng lên nếu anh thực sự cần thêm không gian và khả năng sử dụng đa dạng.', 36, '2026-10-13T00:10:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fbe8be73a0a94c81b72642827b1616cd', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Anh chỉ sợ mua VF 3 xong được một năm lại thấy chật.', 37, '2026-10-13T00:13:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f94ff7ec3ef44d50a89dc053f397cc6b', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Cái đấy có khả năng xảy ra, nhất là con anh lớn thêm, gia đình bắt đầu mang nhiều đồ khi đi chơi.', 38, '2026-10-13T00:16:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2fba7bd66f614c3b8a315ef990787f67', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Hay thế này, anh thử đưa cả vợ con qua xem xe. Cho bé ngồi thử ghế sau, đặt thử ghế trẻ em và xem cốp có đủ đồ không. Cảm nhận thực tế sẽ dễ quyết hơn.', 39, '2026-10-13T00:19:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('86928ba2175e469194be92256782fb9d', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Nghe hợp lý. Nhưng vợ anh lại đang thích xe xăng. Bảo xe điện vài năm pin hỏng là vứt.', 40, '2026-10-13T00:22:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a23c42c3cd81484487037b38780c04c9', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Cái này chắc nhiều nhà cũng tranh luận giống nhà anh', 41, '2026-10-13T00:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('473c341249ac42a482a49bada34badba', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Pin không phải cứ dùng vài năm là hỏng. Nhưng em nghĩ chị nhà có quyền lo, vì đây là khoản tiền lớn.', 42, '2026-10-13T00:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5f8468900126435580a3f4e61547ce2a', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'VF 3 hiện công bố bảo hành xe 7 năm hoặc 160.000 km, còn chính sách bảo hành pin phải xem chi tiết theo điều khoản áp dụng cho xe mình mua.', 43, '2026-10-13T00:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6f9a58633a3a4e509f4a78e460933ce9', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Thế hết bảo hành mà pin hỏng thì sao? Phải thay cả cục à?', 44, '2026-10-13T00:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ec63b0752e2f4e2dbbf7050077db27c2', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Còn tùy lỗi anh. Không phải trường hợp nào cũng phải thay toàn bộ bộ pin. Cần kiểm tra để xác định bộ phận nào hỏng và phương án sửa chữa.', 45, '2026-10-13T00:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3191445a48ba43f1b9d79b325c388809', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Chi phí thay thế ngoài bảo hành thì em sẽ không đoán, vì phụ thuộc hạng mục và giá linh kiện thời điểm đó.', 46, '2026-10-13T00:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('419116b7b1ac49ec9498f8d9246d7305', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Ừ, nói thế anh còn tin. Chứ mấy ông sales toàn bảo pin dùng cả đời.', 47, '2026-10-13T00:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4233740479cb4320952e30b87a5dada4', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Haha, nói pin dùng cả đời thì em cũng không dám đâu anh. Thiết bị nào cũng có tuổi thọ của nó.', 48, '2026-10-13T00:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3c9fd8b3026249e0bacce4bed7b7c4a1', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Quan trọng là mình hiểu rõ chính sách bảo hành, sử dụng đúng hướng dẫn và có phương án xử lý khi phát sinh vấn đề.', 49, '2026-10-13T00:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('202fbbc73bd941b09138e698588c70b6', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'À mà nếu mua VF 3 thì bên em có sẵn xe giao luôn không?', 50, '2026-10-13T00:52:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6210dd86eeac47399d0a6e05f0150dd7', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Cái này em phải kiểm tra theo màu và phiên bản anh chọn. Anh đang thích màu nào?', 51, '2026-10-13T00:55:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ebfa9c50cf664004a02259239a9e9122', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Anh thích màu xanh. Nhưng vợ anh lại thích màu trắng.', 52, '2026-10-13T00:58:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1c7a2c8d0469404dbad2ca97a2bd9285', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Thế chắc để chị chọn màu cho yên nhà anh ạ', 53, '2026-10-13T01:01:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7c1c63ba83e84efb8a7cc593ef725658', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Haha. Nhưng màu trắng dễ bẩn lắm.', 54, '2026-10-13T01:04:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2115763002c447c0bc59f84cadc6f79b', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Đúng, trắng thì nhìn sạch và sáng xe nhưng đi mưa bùn dễ thấy vết bẩn. Xanh thì nổi bật hơn. Anh có thể qua xem màu thực tế, ảnh trên điện thoại đôi khi lệch màu.', 55, '2026-10-13T01:07:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('77022b080b5d417082e624481b447d65', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Mà anh chưa có bằng lái đâu. Đang học, tháng sau mới thi.', 56, '2026-10-13T01:10:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ca8d0f61c1e24084bc08eaf1ec929093', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'À, thế là mình đang chuẩn bị mua xe trước rồi.', 57, '2026-10-13T01:13:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('61fb732e743e4d10b99466dba511c14b', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Ừ, tính mua luôn sau khi lấy bằng. Nếu đỗ nhé, haha.', 58, '2026-10-13T01:16:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6e23425ce5f64a3cbc21b7efcb5132fc', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Haha, vậy chúc anh thi một lần là qua. Chưa cần vội đặt cọc lúc này đâu. Anh cứ chọn mẫu xe trước, còn chuyện lấy xe mình tính theo thời điểm có bằng.', 59, '2026-10-13T01:19:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8b30090498b14b1299066d028c400b50', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Anh sợ đợi tháng sau lại tăng giá.', 60, '2026-10-13T01:22:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('476fa985269a4962b1ef640e6f880a62', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Giá và ưu đãi có thể thay đổi theo từng đợt, em không đảm bảo trước được.', 61, '2026-10-13T01:25:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7eded002e81a43dab321a2b8d2c9038b', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Nếu có chương trình áp dụng ở thời điểm anh định mua thì em sẽ gửi anh so sánh, nhưng anh đừng vì sợ tăng giá mà cọc khi mình chưa chắc về mẫu xe.', 62, '2026-10-13T01:28:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('77dfc11609bb405f8abba72405c37724', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Ừ. Thế em tính giúp anh 2 phương án nhé. Một cái VF 3 vay 150 triệu, một cái VF 5 vay 300 triệu, trả trong 5 năm.', 63, '2026-10-13T01:31:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fff60603370a4aa6b58b07862d1538b7', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Được anh. Em lấy cùng giả định lãi suất 9%/năm, trả gốc đều để anh dễ so sánh trước nhé.', 64, '2026-10-13T01:34:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0278c4ff837b4101af765d2737cabd5f', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Vay 150 triệu thì tháng đầu khoảng 3,63 triệu, còn vay 300 triệu thì khoảng 7,25 triệu. Các tháng sau sẽ giảm dần nếu lãi suất giữ nguyên.', 65, '2026-10-13T01:37:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3c9a94de18764df6ab1a73abd7d03b83', 'be77752496eb4fb5b95889ba203e97e2', 'customer', '7 triệu thì cao quá. Thôi VF 5 chắc bỏ.', 66, '2026-10-13T01:40:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('078564d2b2da4e5fa887503842d57008', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Vậy mình tập trung VF 3 trước. Vay 150 triệu cũng gần với mức anh muốn trả hằng tháng hơn.', 67, '2026-10-13T01:43:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b9dc2ca308d34d12aa80f300c2bf3f7a', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Nhưng em khuyên anh đừng dồn hết 150 triệu tiền mặt vào xe. Nên giữ lại một khoản dự phòng cho gia đình.', 68, '2026-10-13T01:46:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('9ac4d29c914845c0bd8f917894a14d05', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Đúng rồi. Anh cũng nghĩ thế. Thế 150 triệu vay thì ngân hàng có dễ duyệt không?', 69, '2026-10-13T01:49:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5ae5ad84c7c647ffb5d397064300b6e4', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Còn tùy thu nhập, lịch sử tín dụng và hồ sơ của anh. Nếu công việc và thu nhập ổn định thì có cơ sở để ngân hàng xem xét, nhưng em không thể hứa chắc là duyệt.', 70, '2026-10-13T01:52:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6c19cfda1d7c4074abb9c1bdf53c6763', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Anh làm văn phòng, lương chuyển khoản khoảng 18 triệu. Vợ anh cũng đi làm nhưng anh muốn tự đứng tên vay.', 71, '2026-10-13T01:55:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b0cb3fbc3a9649be8038042671ff8ae7', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Dạ, vậy mình có thể chuẩn bị hồ sơ để ngân hàng đánh giá. Em sẽ gửi anh danh sách giấy tờ cơ bản và nhờ bên hỗ trợ tài chính tư vấn phương án phù hợp.', 72, '2026-10-13T01:58:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4f706bca1e634ce6af9332ff90dc469d', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Ok. Em cứ gửi bảng trả góp trước nhé. Anh bàn thêm với vợ đã.', 73, '2026-10-13T02:01:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4fc8068fb3ca41df9fb7da933f34a165', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Vâng anh. Em sẽ gửi hai phương án có lãi suất giả định và ghi rõ phần nào cần ngân hàng xác nhận, để hai vợ chồng dễ cân nhắc.', 74, '2026-10-13T02:04:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('72bde3dbe80547f7ba96683d157e0be5', 'be77752496eb4fb5b95889ba203e97e2', 'customer', 'Ừ, cảm ơn em.', 75, '2026-10-13T02:07:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('90525d28267943a49c0a86ea4bacb010', 'be77752496eb4fb5b95889ba203e97e2', 'sales', 'Dạ không có gì anh. Khi nào hai vợ chồng muốn qua xem xe thì nhắn em, em sắp xếp để mình xem cả VF 3 lẫn VF 5 luôn.', 76, '2026-10-13T02:10:56.910229+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3fb11ef470b04539be16cc91993b0821', 'be77752496eb4fb5b95889ba203e97e2', 'sales', '[Kiểm thử hệ thống 16/10] Kiểm tra lưu tin nhắn trong hội thoại.', 77, '2026-10-16T03:45:30.987268+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fe169cb0093442eb9a3f3213ea6464c7', 'be77752496eb4fb5b95889ba203e97e2', 'sales', '[Kiểm thử web 16/10] Xác nhận nút Gửi lưu được tin nhắn.', 78, '2026-10-16T03:57:08.125864+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('90e2b96026cb42cb8ca42e2aa303f46c', 'c27a88add9314e16a78dbdc0831e9c11', 'sales', 'Em chào anh Phong ạ! Em là Minh Anh bên VinFast. Hôm trước anh có hỏi về mẫu VF 7 bản Eco và bản Plus, hôm nay em nhắn cập nhật chương trình ưu đãi tháng này cho anh ạ.', 1, '2026-10-17T09:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f9ed5ec27f144a1c9d9444d7ceb336a3', 'c27a88add9314e16a78dbdc0831e9c11', 'customer', 'Chào em, anh ở khu đô thị An Khánh, Hoài Đức, hàng ngày chạy đại lộ Thăng Long vào nội thành làm việc khoảng 35 km cả đi lẫn về.', 2, '2026-10-17T09:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('788d0f77633e47ae89c4fe49f2d2bd27', 'c27a88add9314e16a78dbdc0831e9c11', 'sales', 'Dạ chạy đại lộ Thăng Long mỗi ngày mà đi VF 7 thì cực kỳ sướng anh ạ, thân xe rộng 1.890 mm đầm chắc và cách âm gầm ở dải tốc độ 80-100 km/h rất tốt.', 3, '2026-10-17T09:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('77c8520565ed4de69f444b05ff8fab3b', 'c27a88add9314e16a78dbdc0831e9c11', 'customer', 'Anh đang cân nhắc bản VF 7 Eco vì tài chính anh chỉ muốn chi khoảng 780 - 800 triệu lăn bánh thôi. Bản Eco so với bản Plus bị cắt những gì quan trọng hả em?', 4, '2026-10-17T10:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8e8a2a28b0a744169155b6a44f49f7f7', 'c27a88add9314e16a78dbdc0831e9c11', 'sales', 'Dạ VF 7 Eco vẫn giữ nguyên thiết kế ngoại thất tương lai, màn hình giải trí 12,9 inch, HUD kính lái và không gian nội thất rộng rãi như bản Plus. Điểm khác biệt chính là bản Eco dẫn động 1 cầu 174 mã lực, mâm 19 inch và chưa có gói ADAS nâng cao như bản Plus ạ.', 5, '2026-10-17T10:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0aca8bdf04304ca0b62ce108068f6cde', 'c27a88add9314e16a78dbdc0831e9c11', 'customer', 'Giá lăn bánh VF 7 Eco mua kèm pin ở Hà Nội hiện tại là bao nhiêu?', 6, '2026-10-17T10:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('dd5be9c34c514872abbb2aed0db9f167', 'c27a88add9314e16a78dbdc0831e9c11', 'sales', 'Dạ VF 7 Eco kèm pin sau khi áp dụng ưu đãi hiện hành và cộng 20 triệu biển số Hà Nội thì tổng lăn bánh rơi vào khoảng 785 - 795 triệu đồng, nằm đúng trong khoảng 800 triệu của anh luôn ạ!', 7, '2026-10-17T10:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a6d353002a2b4dce9a2f563b631d8016', 'c27a88add9314e16a78dbdc0831e9c11', 'customer', 'Nếu so với Ford Territory bản Titanium thì VF 7 Eco có ưu thế gì hơn không em? Vợ anh lại đang thích Territory.', 8, '2026-10-17T10:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('67e7816a4b88441691f3182481c7ae0c', 'c27a88add9314e16a78dbdc0831e9c11', 'sales', 'Dạ so với Territory thì VF 7 Eco có chiều dài cơ sở lớn hơn (2.840 mm so với 2.726 mm), hệ thống treo sau đa liên kết êm ái, chân ga điện mượt không bị trễ turbo, và đặc biệt anh tiết kiệm được khoảng 70-80 triệu tiền thuế trước bạ cộng với tiền xăng hằng tháng ạ.', 9, '2026-10-17T10:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('68321b301e1d494d95912ad46dde13dc', 'c27a88add9314e16a78dbdc0831e9c11', 'customer', 'Nhà anh liền kề ở An Khánh có gara riêng. Khi mua xe có được tặng kèm bộ sạc tại nhà không hay phải mua ngoài?', 10, '2026-10-17T10:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('147e054aeeb14efbae50e79acd0cedaf', 'c27a88add9314e16a78dbdc0831e9c11', 'sales', 'Dạ anh có thể mua bộ sạc treo tường chính hãng 7,4 kW hoặc bộ sạc di động 3,5 kW. Hiện bên đại lý em đang có chương trình hỗ trợ ưu đãi phụ kiện hoặc khảo sát lắp đặt tận nhà tại Hoài Đức cho khách đặt xe trong tháng này ạ.', 11, '2026-10-17T10:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('115dd11a7f6540a3982fa16532cf16a1', 'c27a88add9314e16a78dbdc0831e9c11', 'customer', 'Anh muốn trả trước 500 triệu, vay thêm khoảng 290 triệu trong 4 năm để giữ lại ít tiền mặt xoay vòng kinh doanh.', 12, '2026-10-17T10:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7cd8ba0321594fcaac7ddfd60a46cd35', 'c27a88add9314e16a78dbdc0831e9c11', 'sales', 'Dạ vay 290 triệu trong 4 năm (48 tháng) thì mỗi tháng tiền gốc khoảng 6 triệu cộng lãi khoảng hơn 1,8 triệu, rất nhẹ nhàng cho dòng tiền kinh doanh của anh ạ.', 13, '2026-10-17T10:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3065d1987c9f42fb988602b9a364244a', 'c27a88add9314e16a78dbdc0831e9c11', 'customer', 'Ok em, gửi bảng tính trả góp 48 tháng và giữ lịch sáng Chủ nhật 8h30 anh chở bà xã qua chạy thử cả VF 7 để thuyết phục vợ nhé.', 14, '2026-10-17T10:30:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e2fe1bf582864855a1fef6134427abe6', 'c37a7bca5a094ac8aded3518c17c96c7', 'sales', 'Em chào anh Hoàng ạ! Em là Minh Anh bên VinFast. Em thấy anh quan tâm mẫu VF 3 và VF 5, không biết anh đang cân nhắc nhu cầu sử dụng như thế nào để em tư vấn so sánh giúp anh ạ?', 1, '2026-10-17T13:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1c6f29531d914e0997745680a59d591a', 'c37a7bca5a094ac8aded3518c17c96c7', 'customer', 'Chào em, anh ở Đông Anh, muốn mua xe cho vợ đi dạy học cách nhà 8 km và thỉnh thoảng hai vợ chồng cùng 2 con nhỏ sang nội thành chơi cuối tuần.', 2, '2026-10-17T13:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4e8712bf6887475b8b78325f842e2746', 'c37a7bca5a094ac8aded3518c17c96c7', 'sales', 'Dạ nếu chị nhà chỉ đi dạy học một mình 8 km thì VF 3 rất gọn, nhưng nếu cuối tuần cả gia đình 4 người hay sang nội thành qua cầu Nhật Tân hoặc đi chơi xa kèm đồ đạc thì em khuyên anh nên cân nhắc kỹ VF 5 Plus vì có 5 cửa và cốp rộng hơn hẳn ạ.', 3, '2026-10-17T13:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('59ceff475dc0427e82b3af3395e09104', 'c37a7bca5a094ac8aded3518c17c96c7', 'customer', 'Hai mẫu đấy chênh nhau khoảng bao nhiêu tiền lăn bánh hả em? Ngân sách hai vợ chồng anh đang có khoảng 350 triệu tiền mặt.', 4, '2026-10-17T14:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3ce722f608594a509fd3e11f01e975cb', 'c37a7bca5a094ac8aded3518c17c96c7', 'sales', 'Dạ VF 3 kèm pin lăn bánh Hà Nội khoảng 315-320 triệu (anh trả thẳng 350 triệu là còn dư tiền). Còn VF 5 Plus kèm pin lăn bánh khoảng 510 triệu, tức là nếu lấy VF 5 thì anh chỉ cần vay trả góp thêm khoảng 160 triệu thôi ạ.', 5, '2026-10-17T14:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('76380927d5e64ba09656bff2c50b526e', 'c37a7bca5a094ac8aded3518c17c96c7', 'customer', 'Vay 160 triệu trong 3 năm thì mỗi tháng đóng bao nhiêu em? Vợ anh giáo viên công lập có bảng lương ổn định.', 6, '2026-10-17T14:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('fcd40bc6a0bd4b59881f1d770ce87b10', 'c37a7bca5a094ac8aded3518c17c96c7', 'sales', 'Dạ giáo viên công lập thì ngân hàng cực kỳ ưu tiên lãi suất tốt anh ạ! Vay 160 triệu trong 36 tháng thì gốc và lãi mỗi tháng chỉ khoảng 5,3 triệu đồng thôi ạ.', 7, '2026-10-17T14:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('260d3b3f1f2c47f18bb4b1553877ed8c', 'c37a7bca5a094ac8aded3518c17c96c7', 'customer', 'VF 3 là 2 cánh cửa nên lúc bọn trẻ con lên xuống hàng ghế sau phải gập ghế trước xuống đúng không em?', 8, '2026-10-17T14:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b9ce09c07fa946ea872405343e570a86', 'c37a7bca5a094ac8aded3518c17c96c7', 'sales', 'Dạ đúng rồi anh ạ, VF 3 thiết kế 2 cửa bên hông nên khi người ngồi sau lên xuống sẽ gập lưng ghế phụ phía trước. Còn VF 5 là SUV 5 cửa truyền thống nên các bé mở cửa sau lên xuống độc lập tiện hơn.', 9, '2026-10-17T14:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c832d025d4f9436b8f63e96294fbed87', 'c37a7bca5a094ac8aded3518c17c96c7', 'customer', 'Ừ thế nghe chừng cố lên VF 5 hợp lý hơn thật, đi được lâu dài 5-7 năm không phải đổi xe. Sạc ở nhà đất Đông Anh thì cắm ổ điện dân dụng có sạc được VF 5 không?', 10, '2026-10-17T14:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('60b0d21d4a2248afb30adffbd1716e8b', 'c37a7bca5a094ac8aded3518c17c96c7', 'sales', 'Dạ hoàn toàn sạc được bằng bộ sạc di động 2,2 kW hoặc 3,5 kW cắm ổ điện có tiếp địa tại nhà anh nhé! Chị đi mỗi ngày 16 km chỉ mất khoảng 5-6% pin, tối thứ Sáu cắm sạc qua đêm đến sáng thứ Bảy là đầy 100% pin cho cả nhà đi chơi cuối tuần.', 11, '2026-10-17T14:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('eff3d4927ece472fb79e7ebfbb5df0f9', 'c37a7bca5a094ac8aded3518c17c96c7', 'customer', 'Hay đấy. Để tối nay anh bàn lại với vợ phương án vay thêm 160 triệu lấy VF 5 màu Trắng hoặc Xanh nhạt, sáng thứ Bảy hai vợ chồng anh sang showroom xem cả VF 3 và VF 5 đặt cạnh nhau rồi chốt luôn.', 12, '2026-10-17T14:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('91ab6a344b91400cb9d2f356953a10c8', 'c641d4d2249f48418e471227c67fee3a', 'sales', 'Dạ em chào anh Bảo ạ! Em là Minh Anh bên VinFast. Em xin phép gửi thông tin mẫu SUV full-size VF 9 mà anh đang tìm hiểu cho gia đình mình ạ.', 1, '2026-10-17T03:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3a9d2d4f27f6419db917e204c81f754f', 'c641d4d2249f48418e471227c67fee3a', 'customer', 'Chào em, đại gia đình anh có 6 người lớn và 1 trẻ nhỏ, đang cân nhắc giữa VF 9 Plus cấu hình 6 ghế Captain với Kia Carnival bản Signature.', 2, '2026-10-17T03:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('793c598d2924485ab773388c6cf0b4ca', 'c641d4d2249f48418e471227c67fee3a', 'sales', 'Dạ nếu nhà mình 6 người lớn kèm 1 bé thì anh nên cân nhắc kỹ giữa bản 6 ghế (2-2-2) và bản 7 ghế (2-3-2) của VF 9 Plus anh ạ! Bản 6 ghế có lối đi ở giữa xuống hàng 3 rất sang, còn bản 7 ghế sẽ ngồi đủ 7 thành viên thoải mái hơn.', 3, '2026-10-17T03:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('733b6baaf214436c94486f14ae1b52e1', 'c641d4d2249f48418e471227c67fee3a', 'customer', 'Ông bà nội anh lớn tuổi nên anh rất thích hàng ghế thứ 2 kiểu thương gia có massage, thông gió, sưởi ấm của bản 6 ghế. Hàng ghế thứ 3 của VF 9 người lớn 1m70 ngồi đi xa có bị bó gối không?', 4, '2026-10-17T04:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('0c39231ff217481c96980a2d5cce373a', 'c641d4d2249f48418e471227c67fee3a', 'sales', 'Dạ VF 9 có chiều dài cơ sở lên tới 3.150 mm nên hàng ghế thứ 3 người cao 1m70-1m75 ngồi duỗi chân vẫn rất rộng rãi, có cửa gió điều hòa và cổng sạc riêng cho từng vị trí luôn anh ạ.', 5, '2026-10-17T04:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('347a4a1e0d504087baee31e7826ad771', 'c641d4d2249f48418e471227c67fee3a', 'customer', 'Dung lượng pin CATL của VF 9 hiện tại đi thực tế cao tốc được bao nhiêu km? Anh hay chở cả nhà đi Quảng Ninh, Nghệ An.', 6, '2026-10-17T04:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b8d3b47e9a17459f94349c5213f95db6', 'c641d4d2249f48418e471227c67fee3a', 'sales', 'Dạ VF 9 trang bị bộ pin CATL dung lượng lớn 123 kWh, công bố WLTP lên tới hơn 600 km/lần sạc đầy. Đi thực tế full tải trên cao tốc bật điều hòa mát sâu vẫn đạt khoảng 500 - 530 km, tức là anh chạy một mạch từ Hà Nội vào tận TP Vinh (Nghệ An) không cần dừng sạc giữa đường ạ!', 7, '2026-10-17T04:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b53ce65ab3ac4b1a900cc86e2264dd56', 'c641d4d2249f48418e471227c67fee3a', 'customer', 'Nghe ấn tượng đấy. Hệ thống treo khí nén trên VF 9 Plus bảo hành bao lâu em?', 8, '2026-10-17T04:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('82ce177cdca042d287e0b633fcc6bc2d', 'c641d4d2249f48418e471227c67fee3a', 'sales', 'Dạ VF 9 được hưởng chế độ bảo hành chính hãng 10 năm hoặc 200.000 km đứng đầu thị trường hiện nay anh ạ, ngoài ra còn có dịch vụ cứu hộ 24/7 và đặc quyền chăm sóc dành riêng cho chủ xe VF 9.', 9, '2026-10-17T04:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('60d7b0a414274e558ac0b039a122d373', 'c641d4d2249f48418e471227c67fee3a', 'customer', 'Tổng chi phí lăn bánh bản VF 9 Plus 6 ghế trần kính kèm pin ở Hà Nội bây giờ là bao nhiêu?', 10, '2026-10-17T04:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b2919bd8b5c949849167690dfbe22f24', 'c641d4d2249f48418e471227c67fee3a', 'sales', 'Dạ bản VF 9 Plus 6 ghế kèm pin CATL sau khi trừ các chương trình ưu đãi hiện hành và miễn lệ phí trước bạ thì lăn bánh tại Hà Nội khoảng 1 tỷ 950 triệu đến 2 tỷ đồng ạ.', 11, '2026-10-17T04:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8ef9d037e9c8482895c80eccac587d0e', 'c641d4d2249f48418e471227c67fee3a', 'customer', 'Anh định thanh toán tiền mặt luôn trong tháng tới. Cuối tuần này em sắp xếp xe VF 9 Plus bản 6 ghế để anh đưa ông bà qua ngồi thử hàng ghế thứ 2 được không?', 12, '2026-10-17T04:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1f22afcb20034b1eb4c11edd2f7479e4', 'c641d4d2249f48418e471227c67fee3a', 'sales', 'Dạ vâng ạ! Để em đặt lịch giữ xe VF 9 Plus 6 ghế sẵn sàng tại sảnh chính để ông bà bước lên xe thuận tiện nhất. Anh dự kiến ghé sáng hay chiều Chủ nhật ạ?', 13, '2026-10-17T04:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('88622d26fa8f4f25af859c9b1e4ac37b', 'c641d4d2249f48418e471227c67fee3a', 'customer', 'Sáng Chủ nhật lúc 10h00 nhé em. Chuẩn bị sẵn báo giá lăn bánh chi tiết cả bản 6 ghế và 7 ghế cho anh so sánh luôn.', 14, '2026-10-17T04:30:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('5243f3c29d884591b72ceaad05a2513f', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Em chào anh ạ! Em là Minh Anh, nhân viên tư vấn bán hàng bên VinFast. Không biết anh đang quan tâm đến mẫu xe nào của bên em để em hỗ trợ tư vấn ạ?', 1, '2026-10-16T04:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('009395ba515640289ea1a502d24c5a6b', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Anh chưa xác định được sẽ mua mẫu nào, tài chính anh tầm 700 thì bên em có mẫu nào phù hợp không? Giới thiệu cho anh một vài mẫu đi.', 2, '2026-10-16T04:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('da9f1884c8124a84933dc40963865bb3', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Dạ, tầm 700 triệu thì bên em có mấy mẫu khá phù hợp anh ạ. Ví dụ như VF 5 giá khoảng 496 triệu, VF 6 Eco khoảng 646 triệu, còn VF 6 Plus khoảng 699 triệu.', 3, '2026-10-16T04:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6bff04b3ebc348c68dba2b6e8114b91a', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Nếu anh thích xe rộng và kiểu dáng thể thao hơn thì có thể xem thêm VF 7, nhưng mẫu này giá sẽ cao hơn ngân sách mình một chút.', 4, '2026-10-16T04:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('39f39aec77974637b461a5af2ee51e38', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Trong các mẫu trên thì em thấy VF 6 khá đáng cân nhắc, xe 5 chỗ, không gian ổn, đi phố hay đi xa đều được.', 5, '2026-10-16T04:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4b67339b2d80424d912c0b1b4a3b940f', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Mà 700 triệu này là anh tính cả chi phí lăn bánh luôn hay chỉ riêng tiền xe thôi ạ?', 6, '2026-10-16T04:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('df0649aefa3c4d4385a7449f1a2d8751', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', '700 triệu là tổng chi phí lăn bánh luôn em ạ, nhu cầu anh cũng cơ bản thôi, đi lại hằng ngày miễn sao pin ok tí là được.', 7, '2026-10-16T04:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b09ae9f381224044b20dd31c1ad5e8ca', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Dạ, thế thì em nghiêng về VF 6 Eco hơn anh ạ. Bản này có quãng đường di chuyển công bố khoảng 485 km mỗi lần sạc đầy theo chuẩn NEDC.', 8, '2026-10-16T04:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('201e3d244904476ba569197bcd1ad9c0', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'So với VF 5 thì VF 6 rộng rãi, thoải mái hơn, mà vẫn có khả năng nằm trong ngân sách của anh nếu tính các ưu đãi phù hợp.', 9, '2026-10-16T04:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b2f52e5484914c7fa466cbec218aad19', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Bình thường một ngày anh đi khoảng bao nhiêu km nhỉ? Để em tính thử xem tần suất sạc có tiện cho anh không.', 10, '2026-10-16T04:39:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('d18dec71324b48058d49a36810f3fc22', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Chắc khoảng 30–40 km đó em.', 11, '2026-10-16T04:42:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a0ab27c549aa4c8d9c98dd11a30c00ec', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'À, thế thì cũng không nhiều đâu anh. Nếu đi tầm đấy thì VF 6 Eco đáp ứng khá thoải mái.', 12, '2026-10-16T04:45:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c27b7f19a9f346918581038a9be332fd', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Quãng đường thực tế còn tùy cách chạy và điều hòa, nhưng với mức sử dụng của anh thì thường không cần sạc mỗi ngày.', 13, '2026-10-16T04:48:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1aa5e095184b464ab8e86b81e979d56a', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Mà anh đang ở nhà riêng hay chung cư nhỉ? Vì xe điện thì em nghĩ mình cũng nên tính trước chỗ sạc cho thuận tiện.', 14, '2026-10-16T04:51:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('760b2e09d5af440eaca5a1baa934831b', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Anh đang ở chung cư ở khu vực Long Biên em ạ.', 15, '2026-10-16T04:54:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cd444a59b2634fa296702413ee35b5ee', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Dạ, Long Biên cũng có một số điểm sạc VinFast anh ạ. Nhưng quan trọng nhất vẫn là có trạm nào gần chung cư của mình không.', 16, '2026-10-16T04:57:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8a4d95dcaebe427fa141dbe75b3de21a', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Nếu ngay dưới hầm có trạm sạc thì quá tiện rồi. Còn nếu phải đi xa để sạc thì mình nên cân nhắc kỹ hơn một chút.', 17, '2026-10-16T05:00:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('e6cb63f90dfd42d38c08d954b7368fcb', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Anh ở chung cư nào bên Long Biên vậy ạ? Em xem thử khu vực gần đó có điểm sạc phù hợp không.', 18, '2026-10-16T05:03:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ab88ce7742c24fdaa044187a3fd35923', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Với giá 700 thì nếu chiếc em giới thiệu so với CX-5 thì đâu hơn mấy đâu nhỉ?', 19, '2026-10-16T05:06:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4f66dc1cce034652ab0c81f0e8be1263', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'À, anh đang tham khảo cả Mazda CX-5 nữa đúng không ạ? 😄', 20, '2026-10-16T05:09:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('65b622fcdc8441228819847e6a633103', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Đúng là giá xe hai bên không cách nhau quá nhiều nếu chỉ nhìn giá niêm yết. Nhưng CX-5 bản Deluxe giá khoảng 699 triệu thì lăn bánh ở Hà Nội thường sẽ cao hơn 700 triệu, còn tùy ưu đãi đại lý nữa.', 21, '2026-10-16T05:12:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1af522d36d624fb2a1bca58d22e8d18d', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'VF 6 Eco thì có lợi thế về chi phí sử dụng, xe chạy êm và bảo dưỡng cũng có thể tiết kiệm hơn.', 22, '2026-10-16T05:15:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('7880b8e7a0ee41caa8a9eb80bad61b7f', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Còn CX-5 là SUV hạng C nên không gian rộng hơn, với xe xăng thì đi xa cũng chủ động hơn về việc tiếp nhiên liệu.', 23, '2026-10-16T05:18:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3082d28a0d2045b9a037a03f841adb81', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Anh đang thích CX-5 vì kiểu dáng hay vì không gian xe rộng hơn ạ?', 24, '2026-10-16T05:21:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('72307b691b2141cfb5d4a919abc79bc2', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Anh thấy không gian CX-5 khá rộng rãi.', 25, '2026-10-16T05:24:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('f2294fd9c86c411990da1ccc00401324', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Dạ, cái này thì em đồng ý với anh. CX-5 thuộc phân khúc cao hơn VF 6 nên không gian tổng thể và cốp xe có lợi thế hơn.', 26, '2026-10-16T05:27:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c3e2f9f05bc24229a1ec54bd700c42ae', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Nếu anh ưu tiên xe rộng thì bên em có VF 7 Eco cũng thuộc phân khúc SUV hạng C, anh có thể tham khảo thêm. Mẫu này thiết kế thể thao, chiều dài cơ sở lớn nên chỗ để chân hàng ghế sau khá thoải mái.', 27, '2026-10-16T05:30:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('c4b0728ed032488e9f39ba4eb78de8b6', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'customer', 'Có điều VF 7 sẽ hơi vượt ngân sách 700 triệu lăn bánh ban đầu của anh.', 28, '2026-10-16T05:33:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b9563a4171064e5e901b6897a89174e8', 'd2c000c9a4fe4efc9f61eaa1a7d892fe', 'sales', 'Mà bình thường anh chủ yếu đi một mình hay hay chở gia đình nữa ạ? Nếu thường xuyên đi 4–5 người thì em nghĩ nên ưu tiên không gian xe ngay từ đầu.', 29, '2026-10-16T05:36:08.142591+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('32fc6a15abb4466799b26ab7d4289b3c', 'd495228d223c473a8e2047e693c0b24f', 'sales', 'Dạ em chào chị Hương ạ! Em là Minh Anh bên showroom VinFast Phạm Văn Đồng. Hôm qua chị có để lại thông tin quan tâm dòng xe gầm cao đi phố, em nhắn hỗ trợ chị chi tiết nhé ạ.', 1, '2026-10-16T04:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('519634157cfa44158ab0de24d78f2489', 'd495228d223c473a8e2047e693c0b24f', 'customer', 'Chào em, chị đang tìm xe đi làm hằng ngày từ Cầu Giấy sang Hoàn Kiếm, thỉnh thoảng cuối tuần chở hai bé về ngoại ở Bắc Ninh.', 2, '2026-10-16T04:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('2c8c109130254d94a5d70aa0b62ec8d4', 'd495228d223c473a8e2047e693c0b24f', 'sales', 'Dạ với cung đường đi phố kết hợp về quê khoảng 40-50 km cuối tuần như vậy thì dòng B-SUV là cực kỳ hợp lý chị ạ. Hiện chị đang nghiêng về mẫu VF 5 hay VF 6 hơn ạ?', 3, '2026-10-16T04:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ac5255c7c7a547c99d3fd43c2ec188c2', 'd495228d223c473a8e2047e693c0b24f', 'customer', 'Chị thích kiểu dáng VF 6 hơn vì nhìn mềm mại, nội thất cũng đẹp hơn VF 5. Nhưng chị đang phân vân bản Eco với bản Plus khác nhau nhiều không em?', 4, '2026-10-16T05:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('560eca2873bf44caaf6c46da2cd65c5e', 'd495228d223c473a8e2047e693c0b24f', 'sales', 'Dạ VF 6 Eco và VF 6 Plus dùng chung khối pin LFP 59,6 kWh nhưng khác nhau về công suất và trang bị tiện nghi chị ạ. Bản Plus có ghế da chỉnh điện, làm mát ghế trước, màn hình HUD, mâm 19 inch và gói ADAS đầy đủ hơn.', 5, '2026-10-16T05:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6563632c229c4aa6868846543f766fb6', 'd495228d223c473a8e2047e693c0b24f', 'customer', 'Giá lăn bánh ở Hà Nội cả hai bản kèm pin bây giờ khoảng bao nhiêu em? Chị không muốn thuê pin đâu, mua đứt pin cho đỡ phải nghĩ hằng tháng.', 6, '2026-10-16T05:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a5bb8d107c084c7e8059aaf4acb0c33a', 'd495228d223c473a8e2047e693c0b24f', 'sales', 'Dạ xe điện đang được miễn 100% lệ phí trước bạ nên tại Hà Nội mình chỉ mất 20 triệu tiền biển số và khoảng hơn 2 triệu tiền đăng kiểm, bảo hiểm thôi chị ạ. Nếu mua kèm pin thì VF 6 Eco lăn bánh tầm 670 triệu, còn bản Plus tầm 725 triệu sau khi trừ ưu đãi hiện hành ạ.', 7, '2026-10-16T05:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('bccb6aa0b40a487990a3df45df16aee4', 'd495228d223c473a8e2047e693c0b24f', 'customer', 'Ngân sách chị để sẵn khoảng 730 triệu quay đầu, trả thẳng luôn trong tháng này nếu ưng xe. Nhưng chị ở chung cư Vinhomes Skylake thì sạc dưới hầm có dễ không?', 8, '2026-10-16T05:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cfd3dbc0fd1740a9bdb1432db18fcbfd', 'd495228d223c473a8e2047e693c0b24f', 'sales', 'Dạ ở Vinhomes Skylake thì quá thuận lợi luôn chị ơi! Dưới hầm B1, B2 đều có hệ thống trụ sạc V-GREEN cả sạc thường AC lẫn sạc nhanh DC. Chị đi làm mỗi ngày tầm 20 km thì khoảng 1 tuần chị mới cần cắm sạc 1 lần.', 9, '2026-10-16T05:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('1ab6f51918f44bfd8e4cf02da9f44906', 'd495228d223c473a8e2047e693c0b24f', 'customer', 'Ông xã chị cứ bảo xem thêm Yaris Cross bản xăng-điện hybrid, sợ xe thuần điện đi tỉnh lễ Tết phải xếp hàng chờ sạc.', 10, '2026-10-16T05:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a61be200c8c145a48c299a44fbe17d17', 'd495228d223c473a8e2047e693c0b24f', 'sales', 'Dạ em hiểu băn khoăn của anh nhà ạ. Tuy nhiên chị đi Bắc Ninh chỉ khoảng 40 km một chiều, đầy pin VF 6 đi được hơn 380-400 km thực tế nên chị đi khứ hồi 3-4 lần vẫn chưa hết pin, hoàn toàn không phải sạc dọc đường dịp lễ.', 11, '2026-10-16T05:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6e072275e3d446faaa6b06c63bc82def', 'd495228d223c473a8e2047e693c0b24f', 'customer', 'Ừ nhỉ, nghe hợp lý đấy. Thế bản Plus màu trắng nội thất nâu hiện có sẵn xe giao ngay không em?', 12, '2026-10-16T05:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('82a672f909644a27a811eda132aac0d7', 'd495228d223c473a8e2047e693c0b24f', 'sales', 'Dạ để em kiểm tra kho xe miền Bắc xem lô VF 6 Plus màu trắng nội thất nâu tuần này còn suất giao ngay không rồi em báo lại chị trong chiều nay nhé ạ.', 13, '2026-10-16T05:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('a96f111dfd7b4f098daf5e43fbcac122', 'd495228d223c473a8e2047e693c0b24f', 'customer', 'Ok em, kiểm tra giúp chị. Cuối tuần này thứ Bảy khoảng 9h30 sáng chị với anh nhà qua showroom lái thử bản Plus được không?', 14, '2026-10-16T05:30:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('8134be98f35e4a5f9fc091482b650fa8', 'd495228d223c473a8e2047e693c0b24f', 'sales', 'Dạ được chứ ạ! Sáng thứ Bảy 9h30 em chuẩn bị sẵn xe VF 6 Plus tại showroom Phạm Văn Đồng đón anh chị qua trải nghiệm thực tế và gửi bảng tính lăn bánh chi tiết luôn ạ.', 15, '2026-10-16T05:33:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('ee8b9a423ee44762ad5209011d0a4ada', 'd495228d223c473a8e2047e693c0b24f', 'customer', 'Nhắn trước cho chị bảng so sánh thông số Eco với Plus để tối nay chị đưa anh nhà xem trước nhé.', 16, '2026-10-16T05:36:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('dcf7172409c34e79ba7e5843818d6ad9', 'df56f8e55ae44abcbcf6632e371395aa', 'customer', 'Chào bạn, mình đang xem chiếc VF 6 nhưng chưa rõ kích thước xe có vừa ngõ nhà mình ở Đống Đa không.', 1, '2026-10-16T23:51:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('b0ba844e9fbb41d1a73b65987439dc9f', 'df56f8e55ae44abcbcf6632e371395aa', 'sales', 'Dạ em chào chị Ngọc ạ! Kích thước tổng thể của VF 6 là dài 4.238 mm, rộng 1.820 mm và bán kính quay vòng tối thiểu chỉ 5,3 m chị ạ. Ngõ trước cửa nhà chị rộng khoảng bao nhiêu mét ạ?', 2, '2026-10-16T23:54:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('aeccfff8d0fd4b999359fe662998ebb6', 'df56f8e55ae44abcbcf6632e371395aa', 'customer', 'Ngõ nhà mình rộng khoảng 3m8 nhưng cua vào sân hơi vuông góc nên mình hơi lo không biết lùi vào có dễ không.', 3, '2026-10-16T23:57:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('72fc80b744b44eeebea32ffd7fcedb99', 'df56f8e55ae44abcbcf6632e371395aa', 'sales', 'Dạ nếu ngõ 3m8 thì VF 6 vào được chị ạ, nhất là bản VF 6 Plus có sẵn hệ thống Camera 360 độ độ phân giải cao kèm cảm biến quanh xe, giúp mình căn góc tường rất sát và chuẩn xác.', 4, '2026-10-17T00:00:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('026778b5775c4b5799265529c5fade06', 'df56f8e55ae44abcbcf6632e371395aa', 'customer', 'Hay quá, bên em có hỗ trợ mang xe lái thử qua tận nhà để chị thử lùi vào sân luôn được không? Nếu lùi vừa sân là chị chốt lấy luôn đấy.', 5, '2026-10-17T00:03:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('3021fe365f9d4d76a8735a786aef6de5', 'df56f8e55ae44abcbcf6632e371395aa', 'sales', 'Dạ hoàn toàn được chị Ngọc ơi! Bên em có dịch vụ mang xe lái thử tận nhà cho khách hàng để thử trực tiếp cung đường và cổng/sân đỗ xe gia đình ạ.', 6, '2026-10-17T00:06:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('6725fa35dc1446f6958c6596af0e5fc3', 'df56f8e55ae44abcbcf6632e371395aa', 'customer', 'Tài chính chị có sẵn 450 triệu, phần thiếu chị muốn vay trả góp trong 3 năm thôi cho nhanh hết nợ thì mỗi tháng trả khoảng bao nhiêu?', 7, '2026-10-17T00:09:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('cabfca3c14bd4a2a9437415659007de1', 'df56f8e55ae44abcbcf6632e371395aa', 'sales', 'Dạ với VF 6 Plus lăn bánh khoảng 725 triệu, chị trả trước 450 triệu thì chỉ cần vay thêm khoảng 275 triệu trong 36 tháng. Gốc cộng lãi mỗi tháng khoảng hơn 9,2 triệu đồng thôi chị ạ.', 8, '2026-10-17T00:12:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('eb1b1eb45a36475eb9b4b0c2b7177638', 'df56f8e55ae44abcbcf6632e371395aa', 'customer', 'Nếu trả nợ trước hạn sau 1-2 năm thì phí phạt trả trước hạn của ngân hàng tính thế nào em?', 9, '2026-10-17T00:15:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('52b80e97486144b0b7c2eb231fca08ec', 'df56f8e55ae44abcbcf6632e371395aa', 'sales', 'Dạ thường năm đầu phí tất toán trước hạn khoảng 2-3% trên số tiền trả trước, sang năm thứ 2 chỉ còn 1-1,5%, và từ năm thứ 3 trở đi nhiều ngân hàng miễn phí tất toán luôn chị ạ.', 10, '2026-10-17T00:18:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('51bf4b1e898b4aa28c755bc4dfd4b723', 'df56f8e55ae44abcbcf6632e371395aa', 'customer', 'Chị thích màu Xanh dương hoặc màu Xám, nội thất màu đen cho sạch vì nhà có nuôi cún.', 11, '2026-10-17T00:21:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('4ca151613abf4c13aa027882f8adf4da', 'df56f8e55ae44abcbcf6632e371395aa', 'sales', 'Dạ cả màu Xanh dương và màu Xám phối nội thất đen đều rất sạch và bền màu chị ạ. Chị muốn em đánh xe VF 6 Plus qua nhà mình ở Đống Đa vào khung giờ nào thì tiện cho chị nhất ạ?', 12, '2026-10-17T00:24:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
INSERT INTO copilot_chat_messages (id, conversation_id, sender_role, content, seq, sent_at) VALUES ('05ae01b1dd444ade992c400a9175d73a', 'df56f8e55ae44abcbcf6632e371395aa', 'customer', 'Chiều thứ Bảy tuần này tầm 16h nhé, lúc đấy ngõ vắng người đi lại dễ thử cổng hơn. Nhắn xác nhận lịch giúp chị.', 13, '2026-10-17T00:27:46.542265+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id = EXCLUDED.conversation_id, sender_role = EXCLUDED.sender_role, content = EXCLUDED.content, seq = EXCLUDED.seq, sent_at = EXCLUDED.sent_at;
