INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('06ce3e6b6c3e41c28e23483aa70ac8c8', 'Chị đang cân nhắc VF 3 làm xe nhỏ thứ hai để đưa đón con và đi chợ quanh Ocean Park; mới lái nên còn băn khoăn chuyện lùi chuồng và chỗ cho hai bé cùng cặp sách. Được tư vấn rằng hàng ghế sau đủ chỗ cho hai bé, xe có cảm biến lùi và camera có thể lắp thêm; hiện chị đang bàn với chồng để chọn màu Vàng nóc trắng hay chờ màu Hồng phấn.', '', '[]', '[]', '[]', 1, '2026-10-17T20:02:35.737317+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('2f56ed8c652947c69163dbcce6d39f58', 'Khách đang cân nhắc VF 6 Eco và Mazda CX-5, với ngân sách 700 triệu đồng đã gồm chi phí lăn bánh; khách đi hằng ngày khoảng 30–40 km và ưu tiên chi phí sử dụng hợp lý, xe êm, pin ổn. Khách đánh giá CX-5 rộng rãi và chủ động hơn khi đi xa, nhưng chưa xác định được điểm sạc phù hợp tại chung cư Long Biên và chưa rõ nhu cầu chở gia đình thường xuyên đến mức nào.', '', '[]', '["Có trạm sạc trong hầm hoặc gần chung cư Long Biên của khách không?", "Khách đang cân nhắc những điểm nào giữa VF 6 Eco và CX-5?"]', '[]', 1, '2026-10-17T18:34:27.682415+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('398a18b8b26c4f06a4a27ee3a4e4f4d0', 'Khách đang cân nhắc VF 6 Eco với Kia Seltos bản tiêu chuẩn; VF 6 Eco màu Trắng và Đỏ hiện có xe, giá lăn bánh kèm pin tại Hà Nội khoảng 670 triệu đồng. Khách dự kiến trả trước 350 triệu, vay 320 triệu trong 5 năm với khoản trả góp ước tính 7,4 triệu đồng/tháng; quanh Văn Quán có điểm sạc nhanh tại Hồ Gươm Plaza và một số tuyến đường lân cận. Khách muốn đưa bé đến ngồi thử vào Chủ nhật khoảng 15h và đề nghị gửi bảng tính trả góp trước; vẫn băn khoăn về phanh tái sinh và việc không sạc qua đêm tại nhà.', '', '[]', '["Khách đề nghị cho bé qua ngồi thử vào Chủ nhật tuần này khoảng 15h00 và yêu cầu gửi trước bảng tính trả góp vay 320 triệu."]', '[]', 2, '2026-10-17T20:51:24.272808+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('3f1203aa553647058bc773ceb9dbf612', 'Khách đang nhắm VF 7 Plus 2 cầu trần kính, băn khoăn mức tiêu thụ pin so với bản 1 cầu và độ nóng của trần kính; bản 2 cầu được báo quãng đường WLTP 431 km, thực tế khoảng 360–380 km, còn chưa có so sánh trực tiếp với bản 1 cầu. Khách hỏi lắp sạc 7,4 kW tại nhà và thu cũ đổi mới CX-5; khoản vay 60 tháng được ước tính tháng đầu hơn 10,5 triệu đồng, nhưng bảng tính chi tiết và lịch thẩm định CX-5 chiều Chủ nhật lúc 14h30 vẫn chưa được xác nhận.', '', '[]', '["Bản 2 cầu có tốn pin hơn bản 1 cầu khá nhiều không?", "Có thể gửi bảng tính dòng tiền trả góp 60 tháng và hẹn bên thẩm định xe cũ đến xem CX-5 chiều Chủ nhật tuần này lúc 14h30 không?"]', '[]', 2, '2026-10-17T20:06:48.412915+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('518f872cafdd47ae8ed54c7ae61f6beb', 'Khách chọn VF 3 màu Xám xi măng, mua đứt pin và thanh toán thẳng, đồng thời yêu cầu giữ xe; dự kiến sáng mai lúc 10h đến showroom đặt cọc và ký hợp đồng. Đại lý báo combo phụ kiện khoảng 18–22 triệu đồng tùy mẫu mâm và cho biết bảo hành pin, động cơ vẫn được giữ nếu tuân thủ thông số lốp và quy định lắp phụ kiện.', '', '[]', '[]', '[]', 4, '2026-10-18T02:44:54.617836+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('8788e91054e34a45ac86599d3baaf207', 'Anh đang cân nhắc VF 5 Plus để chạy Xanh SM, chở khách quen đi sân bay và phục vụ gia đình, với quãng đường dự kiến 180–220 km/ngày; hiện có khoảng 140 triệu đồng tiền mặt. Khoản vay 400 triệu trong 6 năm được ước tính trả 8,2–8,5 triệu đồng/tháng; sales cho biết có thể xét vay không cần hợp đồng lao động qua sao kê hoặc hồ sơ tín dụng, nhưng danh sách giấy tờ cần chuẩn bị vẫn chưa được cung cấp.', '', '[]', '["Cần chuẩn bị những giấy tờ nào để làm hồ sơ thẩm định vay?"]', '[]', 1, '2026-10-17T20:02:33.219654+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('896a46aa394b41b18b3c12da5c8cd685', 'Khách đang cân nhắc VF 5 Plus trong ngân sách tối đa 520 triệu đồng gồm đăng ký; mức lăn bánh biển Hà Nội được tư vấn khoảng 505–512 triệu đồng. Khách đi làm ở Duy Tân khoảng 16 km mỗi ngày, đã được giải đáp về thao tác sạc và một số tính năng; chi phí bảo dưỡng so với Kia Sonet hoặc Raize vẫn chưa có số liệu đối chiếu.', '', '[]', '["Chi phí bảo dưỡng định kỳ của VF 5 so với Kia Sonet hay Raize thế nào?", "Gửi ảnh thực tế xe màu Đỏ nóc trắng và Cam nóc trắng."]', '[]', 1, '2026-10-17T21:11:45.597074+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('8b1161f1ef884671a14a953e48968757', 'Khách ở Hà Đông đang cân nhắc VF 8 để phục vụ gia đình 4 người, ưu tiên xe êm, rộng rãi, tiết kiệm và có chỗ sạc tại nhà; ngân sách dự kiến 1 tỷ đồng nhưng cần bán Tucson 2021 trước khi đổi xe. Khách còn băn khoăn về lỗi phần mềm và việc sạc trên các chuyến đi xa; sales sẽ gửi bảng giá, điều kiện bảo hành pin và cập nhật phương án lái thử sáng Chủ nhật.', '', '[]', '["VF 8 hiện có giá thế nào?", "Bảo hành pin bao lâu em?", "Sạc ở nhà có nguy hiểm không?", "Xe điện có phải không tốn tiền bảo dưỡng không?"]', '[]', 1, '2026-10-17T21:12:28.855743+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('a0986c545dd54d858afc2a406be2133f', 'Khách đang cân nhắc VF 8 Lux Plus và Hyundai SantaFe Prestige cho gia đình 4 người, thường đi đường dài đến Mộc Châu và Sapa. Đã trao đổi về cải tiến hệ thống treo, sưởi và trạm sạc trên các tuyến này, giá lăn bánh dự kiến tại Hà Nội cùng màu sơn và thủ tục mua xe đứng tên công ty. Khách đang chờ báo giá đóng dấu đỏ và danh mục hồ sơ xuất hóa đơn cho pháp nhân công ty.', '', '[]', '["Gửi báo giá đóng dấu đỏ cho pháp nhân công ty và danh mục hồ sơ xuất hóa đơn công ty."]', '[]', 1, '2026-10-17T20:01:53.486222+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('a6b7f8a483a4455c9b2d4799d920973e', 'Khách đang cân nhắc đổi Kia Morning 2019 sang VF 6 Plus, dự định trả thẳng bằng tiền sau khi bán xe cũ và không vay ngân hàng. Khách đã được cung cấp thông tin về tính năng hỗ trợ lái và quãng đường Hà Nội–Hải Phòng; giá thu xe cũ và thời điểm giao xe tuần sau vẫn chưa được xác nhận.', '', '[]', '["Kia Morning đời 2019, đi 4 vạn km được định giá khoảng bao nhiêu?", "Có xe giao ngay trong tuần sau không?"]', '[]', 1, '2026-10-17T21:11:00.337284+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('b75f49c4336b48b5864127b632df8e48', 'Khách quan tâm VF 8 Eco để đi công việc hằng ngày qua các khu công nghiệp ở Bắc Ninh, Bắc Giang và Hải Dương, đồng thời lo ngại quãng đường thực tế và thời gian sạc. Sales cho biết xe đi đường trường khoảng 400–420 km mỗi lần sạc đầy, và quãng đường 250 km/ngày không cần dừng sạc giữa đường; xe có gói ADAS, giá lăn bánh tại Hà Nội được báo khoảng 1,06–1,08 tỷ đồng.', '', '[]', '[]', '[]', 1, '2026-10-17T21:08:56.818448+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('be77752496eb4fb5b95889ba203e97e2', 'Khách đang cân nhắc VF 3 cho gia đình 3 người, đi làm ở Cầu Giấy và về Bắc Ninh 1–2 lần/tháng; VF 3 được đánh giá đáp ứng quãng đường nhưng khách còn băn khoăn về không gian và khả năng đi cao tốc. Khách muốn khoản trả góp không quá 5 triệu/tháng trong 5 năm, lo lãi suất thay đổi sau ưu đãi và đang chờ lịch trả nợ chi tiết, đồng thời chưa rõ tình trạng xe sẵn giao theo màu.', '', '[]', '["VF 3 đi cao tốc có ổn không?", "Nếu mua VF 3 thì có sẵn xe giao ngay không?", "Giá xe có thể tăng nếu chờ đến tháng sau không?", "Có thể tính phương án VF 3 vay 150 triệu và VF 5 vay 300 triệu trong 5 năm không?"]', '[]', 1, '2026-10-17T21:14:20.627130+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('c27a88add9314e16a78dbdc0831e9c11', 'Khách đang cân nhắc VF 7 Eco trong khoảng ngân sách 780–800 triệu đồng lăn bánh, chủ yếu đi làm nội thành khoảng 35 km mỗi ngày; nhà có gara riêng và giá VF 7 Eco tại Hà Nội được tư vấn khoảng 785–795 triệu đồng. Khách so sánh xe với Ford Territory Titanium mà vợ yêu thích; các điểm được trao đổi gồm VF 7 Eco có chiều dài cơ sở lớn hơn, treo sau đa liên kết và có thể tiết kiệm chi phí trước bạ, nhiên liệu.', '', '[]', '["Gửi bảng tính trả góp 48 tháng và giữ lịch sáng Chủ nhật 8h30 để khách cùng vợ qua chạy thử VF 7."]', '[]', 1, '2026-10-17T21:11:07.215566+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('c37a7bca5a094ac8aded3518c17c96c7', 'Anh đang nghiêng về VF 5 để vợ đi dạy và gia đình bốn người sử dụng lâu dài; với khoảng 350 triệu đồng tiền mặt, anh đang cân nhắc vay thêm 160 triệu, khoản trả góp được báo khoảng 5,3 triệu đồng mỗi tháng trong 3 năm. Anh cũng đã hỏi về sạc VF 5 tại nhà ở Đông Anh và lối lên xuống hàng ghế sau của VF 3, đồng thời dự định bàn lại với vợ và xem cả hai mẫu tại showroom trước khi quyết định.', '', '[]', '[]', '[]', 1, '2026-10-17T20:05:52.945110+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('c641d4d2249f48418e471227c67fee3a', 'Anh đang cân nhắc VF 9 Plus 6 ghế Captain với Kia Carnival Signature để chở gia đình 7 người đi Quảng Ninh và Nghệ An; đã trao đổi về không gian hàng ghế thứ ba, tầm hoạt động thực tế và chi phí lăn bánh tại Hà Nội. Hai bên hẹn sáng Chủ nhật lúc 10 giờ tại sảnh chính để ông bà ngồi thử hàng ghế thứ hai trên VF 9 Plus.', '', '[]', '["Chuẩn bị báo giá lăn bánh chi tiết cả bản 6 ghế và 7 ghế để khách so sánh."]', '[]', 1, '2026-10-17T21:12:17.606204+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('d495228d223c473a8e2047e693c0b24f', 'Khách đang cân nhắc VF 6 Eco và Plus trong ngân sách khoảng 730 triệu đồng; giá lăn bánh được tư vấn lần lượt khoảng 670 và 725 triệu đồng. Khách đã được trao đổi về việc sạc tại Vinhomes Skylake và quãng đường đi Bắc Ninh, đồng thời hẹn cùng chồng lái thử VF 6 Plus tại showroom Phạm Văn Đồng vào thứ Bảy lúc 9h30; tình trạng xe màu trắng, nội thất nâu vẫn cần xác nhận.', '', '[]', '["Bản Plus màu trắng nội thất nâu hiện có sẵn xe giao ngay không?", "Nhắn trước bảng so sánh thông số Eco với Plus để khách đưa chồng xem tối nay."]', '[]', 1, '2026-10-17T21:13:03.368154+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
INSERT INTO copilot_memories (conversation_id, quick_summary, detailed_summary, timeline_json, pending_items_json, key_promises_json, version, updated_at) VALUES ('df56f8e55ae44abcbcf6632e371395aa', 'Khách đang cân nhắc VF 6 tại Đống Đa, dự kiến trả trước 450 triệu đồng và vay trong 3 năm; được tư vấn khoản vay khoảng 275 triệu đồng sẽ trả hơn 9,2 triệu đồng mỗi tháng. Khách lo xe khó lùi qua góc vuông vào sân; đã được gợi ý bản Plus có camera 360 độ và cảm biến, cùng dịch vụ lái thử tại nhà. Lịch lái thử chiều thứ Bảy khoảng 16h vẫn đang chờ xác nhận.', '', '[]', '["Xác nhận lịch lái thử tại nhà chiều thứ Bảy tuần này khoảng 16h?"]', '[]', 1, '2026-10-17T20:01:50.929788+00:00') ON CONFLICT (conversation_id) DO UPDATE SET quick_summary = EXCLUDED.quick_summary, detailed_summary = EXCLUDED.detailed_summary, timeline_json = EXCLUDED.timeline_json, pending_items_json = EXCLUDED.pending_items_json, key_promises_json = EXCLUDED.key_promises_json, version = EXCLUDED.version, updated_at = EXCLUDED.updated_at;
