INSERT INTO copilot_intelligence_analyses (id, customer_id, previous_id, requested_at, published_at, payload_json) VALUES ('0f9ae1502dfa4f3bab0df0063d1e502c', '0efe7bb198f24855a681e7ad4bc26485', 'b5f9f43f99cc4ac8b5b47a6496104f06', '2026-10-17T20:51:17.280841+00:00', '2026-10-17T20:51:24.272808+00:00', '{"events": [{"accepted": false, "action": "Khách đang cân nhắc giữa VF 6 Eco và Kia Seltos bản tiêu chuẩn.", "activity_kind": "other", "actor": "customer", "conditional": false, "decision_changed": false, "deferred": false, "ends_at": null, "event_type": "evaluating", "evidence": [{"message_id": "f80b3cc1f3ba44bc8c7b505940792dce", "quote": "chị đang xem giữa VF 6 Eco với Kia Seltos bản tiêu chuẩn."}], "id": "7084a50943172d6e4a788d588103472deec4957e2f694fcc4f2149775762cdb7", "location": "", "occurred_at": "2026-10-17T15:54:46.542265+00:00", "operation": "create", "starts_at": null, "target_event_id": null, "target_task_id": null}], "fact_history": [{"condition": "", "conditional": false, "evidence": [{"message_id": "f80b3cc1f3ba44bc8c7b505940792dce", "quote": "chị đang xem giữa VF 6 Eco với Kia Seltos bản tiêu chuẩn."}], "field": "interested_models", "value": ["VinFast VF 6 Eco"]}, {"condition": "", "conditional": false, "evidence": [{"message_id": "f80b3cc1f3ba44bc8c7b505940792dce", "quote": "chị đang xem giữa VF 6 Eco với Kia Seltos bản tiêu chuẩn."}], "field": "competitor_models", "value": ["Kia Seltos bản tiêu chuẩn"]}, {"condition": "", "conditional": false, "evidence": [{"message_id": "1b678674f6294e039484c4b88cc8cd62", "quote": "Chị có sẵn 350 triệu"}], "field": "down_payment_vnd", "value": 350000000}, {"condition": "", "conditional": false, "evidence": [{"message_id": "1b678674f6294e039484c4b88cc8cd62", "quote": "muốn vay trả góp phần còn lại trong 5 năm."}], "field": "payment_method", "value": "Vay trả góp phần còn lại"}, {"condition": "", "conditional": false, "evidence": [{"message_id": "1b678674f6294e039484c4b88cc8cd62", "quote": "muốn vay trả góp phần còn lại trong 5 năm."}], "field": "loan_term_years", "value": 5}, {"condition": "", "conditional": false, "evidence": [{"message_id": "f80b3cc1f3ba44bc8c7b505940792dce", "quote": "Chị mua xe chủ yếu để hai mẹ con đi lại trong khu Văn Quán, Hà Đông và cuối tuần về quê ở Sơn Tây."}], "field": "usage_purpose", "value": "Hai mẹ con đi lại trong khu Văn Quán, Hà Đông và cuối tuần về quê ở Sơn Tây"}, {"condition": "", "conditional": false, "evidence": [{"message_id": "f80b3cc1f3ba44bc8c7b505940792dce", "quote": "hai mẹ con đi lại"}], "field": "passenger_count", "value": 2}, {"condition": "", "conditional": false, "evidence": [{"message_id": "f80b3cc1f3ba44bc8c7b505940792dce", "quote": "trong khu Văn Quán, Hà Đông"}], "field": "living_area", "value": "Văn Quán, Hà Đông"}, {"condition": "", "conditional": false, "evidence": [{"message_id": "2e859ad78bcf4d05972af974ac975e06", "quote": "Nhà chị ở tập thể cũ không đỗ xe trong nhà để cắm sạc đêm được."}], "field": "charging_condition", "value": "Nhà ở tập thể cũ, không đỗ xe trong nhà để sạc qua đêm"}, {"condition": "", "conditional": false, "evidence": [{"message_id": "255238d0a6da45658a33952cfd56f246", "quote": "Nhưng xe điện phanh tái sinh có làm người ngồi sau bị giật không em?"}, {"message_id": "2e859ad78bcf4d05972af974ac975e06", "quote": "Nhà chị ở tập thể cũ không đỗ xe trong nhà để cắm sạc đêm được."}], "field": "objections_and_concerns", "value": ["Lo phanh tái sinh của xe điện khiến người ngồi sau bị giật", "Không thể sạc xe qua đêm tại nhà"]}, {"condition": "", "conditional": false, "evidence": [{"message_id": "f1327f343b774ba3850e503a7600bfae", "quote": "Màu Trắng hoặc màu Đỏ bản Eco có sẵn xe không em?"}, {"message_id": "bb4937d2bdae41349ac5a81035dd26d4", "quote": "Chiều Chủ nhật tuần này khoảng 15h00 chị cho bé qua ngồi thử"}, {"message_id": "bb4937d2bdae41349ac5a81035dd26d4", "quote": "gửi trước cho chị bảng tính trả góp vay 320 triệu."}], "field": "buying_signals", "value": ["Hỏi xe VF 6 Eco màu Trắng hoặc Đỏ có sẵn không", "Muốn đưa bé đến ngồi thử xe", "Yêu cầu gửi bảng tính trả góp khoản vay 320 triệu"]}], "message_hashes": {"1b678674f6294e039484c4b88cc8cd62": "12fcf9443ab9ed33f457cfc5183652aae4773c513a335db02e921f8a5462eb20", "255238d0a6da45658a33952cfd56f246": "1a68a645f2ae6de753ca6bc1dc8d4faee9683fd9bc7ba3775ae80d5dc228e0b8", "2e859ad78bcf4d05972af974ac975e06": "e7e0bfc4a96df8d93e9bc538b67475ce6f4a4cc9920c740199bfdd6b88a64375", "52c0859e5b7a4bae9f477963a61e7cab": "0bdf70d25a1f826988b56879ea3ec7ab7bccde17f8694a6d55a1459758f4e4e7", "6076b8b8de054005a1886a412f24815e": "053e3cdf3e01ee3482ad6ca20b6f78f750b2607994e2082c0220d9cd99ae061e", "94d422e470b643f98a0984080b24c6fe": "7b928e337afdded5bd9dfacd7ff56632e440da407dd015f3c30bf62b1a0a3025", "bb4937d2bdae41349ac5a81035dd26d4": "bc12a6e9a6661bf75510ea7d19488f02446c3f8acfa2e7d882f4b849b8e510c4", "c82162d3809340389e2c4f9af3baf1af": "229a72c7f8085ab5474dc7c05489dcb0e3c6cc3fbb56f7b814df4c71b7c6cc7b", "e0f1cf6bbdb244c58f3282a104d670d6": "614d024e4008bc4616ee228d6dba988a5ed4f642dc665189636ef4f61439dbe7", "ea03d15e013d46e088c0b143d9f0982d": "b077a76dc5105225dd2ad297a928e13664b18bb62644669a32cacf67ee43a5d8", "f1327f343b774ba3850e503a7600bfae": "1e1635629c02d62656237104837f84f35c354f9c3432c0396c9a719c70f15fec", "f80b3cc1f3ba44bc8c7b505940792dce": "7e7e0e16f1e975847a1f896ef7a8bd3b36af9d62de33eba73782d55c0c6602ed"}, "messages": [{"content": "Dạ em chào chị Nhung ạ! Em là Minh Anh bên VinFast. Em xin phép hỗ trợ thông tin về mẫu xe VF 6 mà chị đang quan tâm nhé ạ.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "94d422e470b643f98a0984080b24c6fe", "sender_role": "sales", "sent_at": "2026-10-17T15:51:46.542265+00:00", "seq": 1}, {"content": "Chào em, chị đang xem giữa VF 6 Eco với Kia Seltos bản tiêu chuẩn. Chị mua xe chủ yếu để hai mẹ con đi lại trong khu Văn Quán, Hà Đông và cuối tuần về quê ở Sơn Tây.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "f80b3cc1f3ba44bc8c7b505940792dce", "sender_role": "customer", "sent_at": "2026-10-17T15:54:46.542265+00:00", "seq": 2}, {"content": "Dạ so với Kia Seltos bản tiêu chuẩn thì VF 6 Eco có lợi thế lớn là được miễn 100% lệ phí trước bạ (tiết kiệm khoảng 75-80 triệu tiền đăng ký), động cơ điện 174 mã lực êm ái không mùi xăng tránh say xe cho bé, và treo sau đa liên kết êm hơn treo thanh xoắn của Seltos ạ.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "e0f1cf6bbdb244c58f3282a104d670d6", "sender_role": "sales", "sent_at": "2026-10-17T15:57:46.542265+00:00", "seq": 3}, {"content": "Con trai chị 7 tuổi đi xe xăng rất hay bị say xe nên chị mới tìm hiểu sang xe điện đấy. Nhưng xe điện phanh tái sinh có làm người ngồi sau bị giật không em?", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "255238d0a6da45658a33952cfd56f246", "sender_role": "customer", "sent_at": "2026-10-17T16:00:46.542265+00:00", "seq": 4}, {"content": "Dạ trên VF 6 mình có thể chỉnh mức phanh tái sinh về mức Thấp hoặc Tắt đi khi đi trong phố, lúc đó xe trôi mượt y hệt xe xăng số tự động nhưng lại hoàn toàn không có tiếng ồn động cơ và mùi xăng nên trẻ nhỏ không bị say xe chị ạ.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "52c0859e5b7a4bae9f477963a61e7cab", "sender_role": "sales", "sent_at": "2026-10-17T16:03:46.542265+00:00", "seq": 5}, {"content": "Tổng lăn bánh VF 6 Eco mua kèm pin ở Hà Nội bây giờ là bao nhiêu em? Chị có sẵn 350 triệu, muốn vay trả góp phần còn lại trong 5 năm.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "1b678674f6294e039484c4b88cc8cd62", "sender_role": "customer", "sent_at": "2026-10-17T16:06:46.542265+00:00", "seq": 6}, {"content": "Dạ VF 6 Eco kèm pin lăn bánh Hà Nội khoảng 670 triệu. Chị trả trước 350 triệu thì chỉ vay ngân hàng 320 triệu trong 5 năm (60 tháng), mỗi tháng đóng cả gốc và lãi khoảng 7,4 triệu đồng thôi ạ.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "ea03d15e013d46e088c0b143d9f0982d", "sender_role": "sales", "sent_at": "2026-10-17T16:09:46.542265+00:00", "seq": 7}, {"content": "Ở quanh hồ Văn Quán Hà Đông có nhiều điểm sạc không em? Nhà chị ở tập thể cũ không đỗ xe trong nhà để cắm sạc đêm được.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "2e859ad78bcf4d05972af974ac975e06", "sender_role": "customer", "sent_at": "2026-10-17T16:12:46.542265+00:00", "seq": 8}, {"content": "Dạ quanh khu Văn Quán, siêu thị Big C Hồ Gươm Plaza và dọc đường Trần Phú, Nguyễn Khuyến đều có cụm trụ sạc nhanh V-GREEN chị ạ! Chị chỉ cần tranh thủ lúc đi siêu thị cuối tuần cắm sạc 30 phút là đủ đi cả tuần lễ luôn.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "c82162d3809340389e2c4f9af3baf1af", "sender_role": "sales", "sent_at": "2026-10-17T16:15:46.542265+00:00", "seq": 9}, {"content": "À ở ngay Hồ Gươm Plaza có trạm sạc thì quá tiện vì tuần nào chị cũng cho bé ra đấy chơi. Màu Trắng hoặc màu Đỏ bản Eco có sẵn xe không em?", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "f1327f343b774ba3850e503a7600bfae", "sender_role": "customer", "sent_at": "2026-10-17T16:18:46.542265+00:00", "seq": 10}, {"content": "Dạ bản VF 6 Eco màu Trắng và màu Đỏ bên em đều đang có xe trong lô phân bổ tháng này chị ạ.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "6076b8b8de054005a1886a412f24815e", "sender_role": "sales", "sent_at": "2026-10-17T16:21:46.542265+00:00", "seq": 11}, {"content": "Chiều Chủ nhật tuần này khoảng 15h00 chị cho bé qua ngồi thử xem cháu có ưng và đỡ mùi xe không nhé, gửi trước cho chị bảng tính trả góp vay 320 triệu.", "conversation_id": "398a18b8b26c4f06a4a27ee3a4e4f4d0", "id": "bb4937d2bdae41349ac5a81035dd26d4", "sender_role": "customer", "sent_at": "2026-10-17T16:24:46.542265+00:00", "seq": 12}], "profile": {"budget_notes": null, "budget_vnd": null, "buying_signals": ["Hỏi xe VF 6 Eco màu Trắng hoặc Đỏ có sẵn không", "Muốn đưa bé đến ngồi thử xe", "Yêu cầu gửi bảng tính trả góp khoản vay 320 triệu"], "charging_condition": "Nhà ở tập thể cũ, không đỗ xe trong nhà để sạc qua đêm", "competitor_models": ["Kia Seltos bản tiêu chuẩn"], "daily_distance_km": null, "down_payment_vnd": 350000000, "facts": [{"confidence": 0.9, "field": "interested_models", "note": null, "source_message_ids": ["f80b3cc1f3ba44bc8c7b505940792dce"], "value": ["VinFast VF 6 Eco"], "verification_status": "reported"}, {"confidence": 0.9, "field": "competitor_models", "note": null, "source_message_ids": ["f80b3cc1f3ba44bc8c7b505940792dce"], "value": ["Kia Seltos bản tiêu chuẩn"], "verification_status": "reported"}, {"confidence": 0.9, "field": "down_payment_vnd", "note": null, "source_message_ids": ["1b678674f6294e039484c4b88cc8cd62"], "value": 350000000, "verification_status": "reported"}, {"confidence": 0.9, "field": "payment_method", "note": null, "source_message_ids": ["1b678674f6294e039484c4b88cc8cd62"], "value": "Vay trả góp phần còn lại", "verification_status": "reported"}, {"confidence": 0.9, "field": "loan_term_years", "note": null, "source_message_ids": ["1b678674f6294e039484c4b88cc8cd62"], "value": 5, "verification_status": "reported"}, {"confidence": 0.9, "field": "usage_purpose", "note": null, "source_message_ids": ["f80b3cc1f3ba44bc8c7b505940792dce"], "value": "Hai mẹ con đi lại trong khu Văn Quán, Hà Đông và cuối tuần về quê ở Sơn Tây", "verification_status": "reported"}, {"confidence": 0.9, "field": "passenger_count", "note": null, "source_message_ids": ["f80b3cc1f3ba44bc8c7b505940792dce"], "value": 2, "verification_status": "reported"}, {"confidence": 0.9, "field": "living_area", "note": null, "source_message_ids": ["f80b3cc1f3ba44bc8c7b505940792dce"], "value": "Văn Quán, Hà Đông", "verification_status": "reported"}, {"confidence": 0.9, "field": "charging_condition", "note": null, "source_message_ids": ["2e859ad78bcf4d05972af974ac975e06"], "value": "Nhà ở tập thể cũ, không đỗ xe trong nhà để sạc qua đêm", "verification_status": "reported"}, {"confidence": 0.9, "field": "objections_and_concerns", "note": null, "source_message_ids": ["255238d0a6da456